const PROFILES_CATALOG_VERSION = 'v20261013_curated_doctors_v1';

function getCuratedInitialProfiles() {
    const currentVersion = localStorage.getItem('caps_pro_profiles_catalog_v');
    let saved = null;
    try {
        const raw = localStorage.getItem('caps_pro_profiles');
        if (raw) saved = JSON.parse(raw);
    } catch (e) {}

    // Se a versão do catálogo mudou ou a lista está vazia, sincroniza com os 4 médicos padrão
    if (currentVersion !== PROFILES_CATALOG_VERSION || !Array.isArray(saved) || saved.length === 0) {
        let list = Array.isArray(saved) ? saved : [];

        // Remove perfil legado dummy 'Administrador' (sem CRM) se existir
        list = list.filter(p => !(p.name === 'Administrador' && (!p.crm || p.crm === '')));

        // Adiciona cada médico oficial se ainda não constar na lista
        CURATED_DEFAULT_PROFILES.forEach(doc => {
            const exists = list.some(p => (p.crm && p.crm === doc.crm) || (p.name && p.name.toUpperCase() === doc.name.toUpperCase()));
            if (!exists) {
                list.push(JSON.parse(JSON.stringify(doc)));
            }
        });

        if (list.length === 0) {
            list = JSON.parse(JSON.stringify(CURATED_DEFAULT_PROFILES));
        }

        try {
            localStorage.setItem('caps_pro_profiles', JSON.stringify(list));
            localStorage.setItem('caps_pro_profiles_catalog_v', PROFILES_CATALOG_VERSION);
        } catch (e) {}

        return list;
    }

    return saved;
}

