// 🔐 MÓDULO DE AUTENTICAÇÃO FIREBASE (GOOGLE LOGIN)
// =========================================================================
App.loginComGoogleFirebase = async function() {
    try {
        if(App.showNotification) App.showNotification("Conectando ao Google...", "info");

        // 1. Importa as bibliotecas oficiais do Firebase direto do servidor deles
        const { initializeApp } = await import("https://www.gstatic.com/firebasejs/10.8.1/firebase-app.js");
        const { getAuth, signInWithPopup, GoogleAuthProvider } = await import("https://www.gstatic.com/firebasejs/10.8.1/firebase-auth.js");

        // ⚠️ ATENÇÃO: COLE AQUI AS SUAS CHAVES DO PASSO 1
        const firebaseConfig = {
            apiKey: "COLE_SUA_API_KEY_AQUI",
            authDomain: "cerebrum-XXXX.firebaseapp.com",
            projectId: "cerebrum-XXXX",
            storageBucket: "cerebrum-XXXX.appspot.com",
            messagingSenderId: "SEU_NUMERO",
            appId: "SEU_APP_ID"
        };

        // 2. Inicializa o motor do Firebase
        const app = initializeApp(firebaseConfig);
        const auth = getAuth(app);
        const provider = new GoogleAuthProvider();
        
        // Força o Google a sempre perguntar qual conta usar
        provider.setCustomParameters({ prompt: 'select_account' });

        // 3. Abre a janelinha (Popup) do Google para o médico escolher a conta
        const result = await signInWithPopup(auth, provider);
        const user = result.user;

        // 🎉 SUCESSO! Capturamos o médico!
        console.log("Médico Logado:", user.displayName, user.email, user.photoURL);

        if(App.showNotification) {
            // Usa o primeiro nome do médico
            const firstName = user.displayName.split(' ')[0];
            App.showNotification(`Bem-vindo ao Cerebrum, Dr(a). ${firstName}!`, "success");
        }

        /* =========================================================
           AQUI VOCÊ DESTRAVA O SISTEMA E ESCONDE A TELA DE LOGIN 
           Exemplo: document.getElementById('login-screen').style.display = 'none';
        ========================================================= */

    } catch (error) {
        console.error("Erro no Firebase Auth:", error.code, error.message);
        if(App.showNotification) {
            if (error.code === 'auth/popup-closed-by-user') {
                App.showNotification("Login cancelado. Você fechou a janela.", "warning");
            } else {
                App.showNotification("Erro ao autenticar com o Google.", "error");
            }
        }
    }
};
