setTimeout(() => {
    // Remove qualquer rastro do estilo legado que deslocava o menu para o centro inferior
    const oldStyle = document.getElementById('apple-menu-css');
    if (oldStyle) oldStyle.remove();

    const floatContainer = document.getElementById('floating-actions-container');
    if (floatContainer) {
        floatContainer.classList.remove('floating-menu-container');
    }

    // A MÁGICA CONTRA A MANCHA AQUI:
    document.querySelectorAll('.float-action-btn, .menu-item').forEach(btn => {
        // Só cria a etiqueta se o botão tiver um 'title' E se esse title não estiver vazio
        if(btn.hasAttribute('title') && btn.getAttribute('title').trim() !== '') {
            const titleText = btn.getAttribute('title');
            btn.setAttribute('data-original-title', titleText);
            btn.removeAttribute('title'); 
        }
    });
}, 300);
