// =========================================================================
// 🚀 CEREBRUM BOOT SEQUENCE (Overdrive: Tamanho e Espaçamento Corrigidos)
// =========================================================================

App.playOverdriveBootSequence = function() {
    if(document.getElementById('overdrive-boot-css')) return;
    
    const style = document.createElement('style');
    style.id = 'overdrive-boot-css';
    style.innerHTML = `
        /* A TELA DE APRESENTAÇÃO */
        #overdrive-splash {
            position: fixed; inset: 0; z-index: 9999999999;
            background-color: #02040a; 
            background-image: radial-gradient(circle at 50% 45%, #081126 0%, #02040a 65%, #000103 100%);
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            overflow: hidden; 
            transition: transform 0.9s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), filter 0.8s ease;
            will-change: transform, opacity, filter;
            cursor: pointer;
        }

        /* GRADE CIBERNÉTICA AMBIENTAL */
        .splash-grid-bg {
            position: absolute; inset: 0;
            background-image: radial-gradient(rgba(56, 189, 248, 0.16) 1.2px, transparent 1.2px);
            background-size: 34px 34px;
            mask-image: radial-gradient(ellipse 70% 70% at 50% 50%, black 20%, transparent 75%);
            -webkit-mask-image: radial-gradient(ellipse 70% 70% at 50% 50%, black 20%, transparent 75%);
            pointer-events: none;
            z-index: 2;
        }

        /* LUZES VOLUMÉTRICAS AMBIENTAIS (GLOW 3D) */
        .ambient-orb {
            position: absolute; border-radius: 50%; filter: blur(110px); pointer-events: none; z-index: 1; opacity: 0.75;
        }
        .ambient-orb-1 {
            width: 480px; height: 480px;
            background: radial-gradient(circle, rgba(56, 189, 248, 0.22) 0%, rgba(14, 165, 233, 0.08) 50%, transparent 70%);
            top: 15%; left: 18%;
            animation: floatOrb1 10s ease-in-out infinite alternate;
        }
        .ambient-orb-2 {
            width: 440px; height: 440px;
            background: radial-gradient(circle, rgba(129, 140, 248, 0.18) 0%, rgba(99, 102, 241, 0.06) 50%, transparent 70%);
            bottom: 15%; right: 18%;
            animation: floatOrb2 12s ease-in-out infinite alternate;
        }
        @keyframes floatOrb1 { 0% { transform: translate(-30px, -20px) scale(0.95); } 100% { transform: translate(30px, 30px) scale(1.1); } }
        @keyframes floatOrb2 { 0% { transform: translate(30px, 20px) scale(1.05); } 100% { transform: translate(-25px, -35px) scale(0.92); } }

        /* CONTAINER CENTRAL PARA TRAVAR O ALINHAMENTO */
        .splash-content-wrapper {
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            position: relative; z-index: 10;
        }

        /* 1. MÓDULO DE MONTAGEM DO LOGO */
        .logo-assembly {
            position: relative; 
            width: 180px; height: 180px;
            display: flex; align-items: center; justify-content: center;
            margin-bottom: 35px;
        }

        /* ONDAS DE ENERGIA (RIPPLES) */
        .ripple-ring {
            position: absolute; inset: 0; margin: auto; 
            width: 124px; height: 124px;
            border: 2px solid #38bdf8; border-radius: 36px;
            opacity: 0; z-index: 1; pointer-events: none;
            animation: emitRipple 2.2s cubic-bezier(0.16, 1, 0.3, 1) infinite;
        }
        .ripple-ring:nth-child(2) { animation-delay: 1.1s; }
        
        @keyframes emitRipple {
            0% { transform: scale(0.92); opacity: 0.8; border-width: 2.5px; }
            100% { transform: scale(2.3); opacity: 0; border-width: 0px; }
        }

        /* 2. O LOGO COM SCANNER LASER SUAVIZADO */
        .splash-logo {
            position: relative; width: 124px; height: 124px;
            background: linear-gradient(135deg, rgba(56,189,248,0.12) 0%, rgba(15,23,42,0.7) 50%, rgba(99,102,241,0.12) 100%); 
            border: 1px solid rgba(56,189,248,0.4); border-radius: 36px;
            display: flex; align-items: center; justify-content: center; 
            z-index: 10; overflow: hidden;
            box-shadow: 0 0 35px rgba(56,189,248,0.22), inset 0 0 25px rgba(56,189,248,0.15), inset 0 1px 0 rgba(255,255,255,0.2);
            backdrop-filter: blur(20px);
        }
        
        .splash-logo-svg {
            filter: drop-shadow(0 0 14px rgba(56, 189, 248, 0.8));
            z-index: 5;
            transition: transform 0.4s ease;
        }
        
        /* FEIXE LASER SUAVIZADO (ATENUADO NAS BORDAS) */
        .scanner-line {
            position: absolute; top: 0; left: 0; width: 100%; height: 3px;
            background: linear-gradient(90deg, 
                transparent 0%, 
                rgba(56, 189, 248, 0.15) 12%, 
                rgba(56, 189, 248, 0.85) 32%, 
                #ffffff 50%, 
                rgba(56, 189, 248, 0.85) 68%, 
                rgba(56, 189, 248, 0.15) 88%, 
                transparent 100%
            );
            box-shadow: 0 0 12px #ffffff, 0 0 26px #38bdf8, 0 0 45px rgba(56, 189, 248, 0.6);
            animation: scanUpDown 1.6s ease-in-out infinite alternate;
            z-index: 10; pointer-events: none;
            border-radius: 3px;
        }
        
        /* VÉU HOLOGRÁFICO QUE SEGUE O SCANNER */
        .scanner-line::after {
            content: '';
            position: absolute;
            top: 100%; left: 0; width: 100%; height: 32px;
            background: linear-gradient(to bottom, rgba(56, 189, 248, 0.22) 0%, rgba(56, 189, 248, 0.04) 65%, transparent 100%);
            pointer-events: none;
            mask-image: linear-gradient(90deg, transparent 0%, black 20%, black 80%, transparent 100%);
            -webkit-mask-image: linear-gradient(90deg, transparent 0%, black 20%, black 80%, transparent 100%);
        }

        @keyframes scanUpDown {
            0% { top: -8%; opacity: 0; }
            12% { opacity: 1; }
            88% { opacity: 1; }
            100% { top: 108%; opacity: 0; }
        }

        /* 3. TEXTO COM VARREDURA DE LUZ */
        .splash-title { 
            font-family: 'Inter', sans-serif; font-size: 2.2rem; font-weight: 900; letter-spacing: 3px; 
            margin: 0 0 6px; text-transform: uppercase; z-index: 10; text-align: center;
            background: linear-gradient(90deg, #94a3b8 0%, #ffffff 50%, #94a3b8 100%);
            background-size: 200% auto; color: #fff;
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            animation: textSweep 3s linear infinite;
        }
        @keyframes textSweep { to { background-position: 200% center; } }
        
        .splash-subtitle { 
            color: #38bdf8; font-family: 'Inter', sans-serif; font-size: 0.82rem; font-weight: 700; 
            letter-spacing: 4.5px; text-transform: uppercase; margin: 0 0 32px; z-index: 10; text-align: center;
            text-shadow: 0 0 12px rgba(56, 189, 248, 0.4);
        }
        
        /* 4. BARRA DE PROGRESSO COM CABEÇA DE COMETA E LEITURA DE PORCENTAGEM */
        .splash-progress-container {
            display: flex; align-items: center; gap: 14px; width: 330px; z-index: 10;
        }
        
        .splash-bar-wrap { 
            flex: 1; height: 7px; background: rgba(15, 23, 42, 0.8); border: 1px solid rgba(255,255,255,0.08); 
            border-radius: 10px; position: relative; box-shadow: inset 0 2px 5px rgba(0,0,0,0.6), 0 0 15px rgba(56,189,248,0.08);
        }
        .splash-bar-fill { 
            height: 100%; width: 0%; 
            background: linear-gradient(90deg, #0284c7 0%, #38bdf8 70%, #ffffff 100%); 
            border-radius: 10px; transition: width 0.35s cubic-bezier(0.16, 1, 0.3, 1); position: relative;
            box-shadow: 0 0 12px rgba(56, 189, 248, 0.6);
        }
        
        .splash-bar-fill::after {
            content: ''; position: absolute; right: -4px; top: -3.5px; width: 14px; height: 14px;
            background: #fff; border-radius: 50%; box-shadow: 0 0 15px #fff, 0 0 30px #38bdf8;
            animation: cometPulse 1.2s ease-in-out infinite alternate;
        }
        @keyframes cometPulse {
            from { transform: scale(0.9); box-shadow: 0 0 12px #fff, 0 0 24px #38bdf8; }
            to { transform: scale(1.15); box-shadow: 0 0 18px #fff, 0 0 36px #38bdf8; }
        }

        .splash-percent-readout {
            font-family: 'Inter', monospace, sans-serif; font-size: 0.78rem; font-weight: 700;
            color: #38bdf8; letter-spacing: 1px; min-width: 38px; text-align: right;
            text-shadow: 0 0 10px rgba(56, 189, 248, 0.5); user-select: none;
        }

        .splash-status { 
            color: #94a3b8; font-family: 'Inter', sans-serif; font-size: 0.75rem; font-weight: 700; 
            text-transform: uppercase; letter-spacing: 2.2px; margin-top: 14px; z-index: 10; text-align: center;
            transition: opacity 0.18s cubic-bezier(0.16, 1, 0.3, 1), transform 0.18s cubic-bezier(0.16, 1, 0.3, 1), color 0.3s, text-shadow 0.3s;
            user-select: none; min-height: 18px;
        }

        /* 5. FAST-SKIP HINT (EXPERIÊNCIA CLÍNICA ÁGIL) */
        .splash-skip-hint {
            margin-top: 24px; font-family: 'Inter', sans-serif; font-size: 0.68rem; font-weight: 600;
            color: rgba(148, 163, 184, 0.6); letter-spacing: 1.5px; text-transform: uppercase;
            display: flex; align-items: center; gap: 8px; z-index: 10; cursor: pointer; user-select: none;
            padding: 6px 14px; border-radius: 20px; background: rgba(255, 255, 255, 0.03);
            border: 1px solid rgba(255, 255, 255, 0.07); backdrop-filter: blur(10px);
            transition: all 0.25s ease; opacity: 0; animation: fadeInHint 0.5s ease 0.4s forwards;
        }
        .splash-skip-hint:hover {
            color: #38bdf8; background: rgba(56, 189, 248, 0.1); border-color: rgba(56, 189, 248, 0.3);
            transform: translateY(-1px);
        }
        .skip-key-badge {
            padding: 2px 6px; border-radius: 5px; background: rgba(255, 255, 255, 0.08);
            border: 1px solid rgba(255, 255, 255, 0.15); font-size: 0.62rem; font-weight: 700; color: #e2e8f0;
        }
        .skip-hint-dot {
            width: 6px; height: 6px; border-radius: 50%; background: #38bdf8; box-shadow: 0 0 8px #38bdf8;
            animation: blinkDot 1.4s ease-in-out infinite;
        }
        @keyframes blinkDot {
            0%, 100% { opacity: 0.3; transform: scale(0.8); }
            50% { opacity: 1; transform: scale(1.2); }
        }
        @keyframes fadeInHint { to { opacity: 1; } }

        /* 6. PARTÍCULAS ORGÂNICAS LUMINOSAS */
        .data-spark {
            position: absolute; border-radius: 50%;
            background: radial-gradient(circle, #ffffff 15%, #38bdf8 70%, rgba(56,189,248,0) 100%);
            box-shadow: 0 0 10px rgba(56, 189, 248, 0.85), 0 0 20px rgba(56, 189, 248, 0.4);
            opacity: 0; pointer-events: none; z-index: 3;
            animation: floatSpark linear forwards;
        }
        @keyframes floatSpark {
            0% { transform: translateY(0) scale(0.5); opacity: 0; }
            20% { opacity: 0.85; transform: translateY(-15vh) scale(1); }
            80% { opacity: 0.8; }
            100% { transform: translateY(-90vh) scale(0.3); opacity: 0; }
        }

        /* A TRANSIÇÃO DE ZOOM */
        #overdrive-splash.zoom-out {
            transform: scale(2.2); 
            opacity: 0; 
            filter: blur(28px);
            pointer-events: none;
        }

        #login-screen {
            animation: landingHUD 1.2s cubic-bezier(0.16, 1, 0.3, 1) forwards !important;
        }
        @keyframes landingHUD {
            0% { transform: scale(0.88); opacity: 0; filter: blur(15px); }
            100% { transform: scale(1); opacity: 1; filter: blur(0); }
        }
    `;
    document.head.appendChild(style);

    // ESTRUTURA HTML
    const splash = document.createElement('div');
    splash.id = 'overdrive-splash';
    splash.title = 'Clique para pular introdução';
    splash.innerHTML = `
        <div class="splash-grid-bg"></div>
        <div class="ambient-orb ambient-orb-1"></div>
        <div class="ambient-orb ambient-orb-2"></div>

        <div class="splash-content-wrapper">
            <div class="logo-assembly">
                <div class="ripple-ring"></div>
                <div class="ripple-ring"></div>
                
                <div class="splash-logo">
                    <div class="scanner-line"></div>
                    <svg class="splash-logo-svg" viewBox="0 0 100 100" width="76" height="76" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <defs>
                        <linearGradient id="asclepiusStaff" x1="50" y1="10" x2="50" y2="90" gradientUnits="userSpaceOnUse">
                          <stop offset="0%" stop-color="#ffffff"/>
                          <stop offset="30%" stop-color="#38bdf8"/>
                          <stop offset="100%" stop-color="#6366f1"/>
                        </linearGradient>
                        <linearGradient id="asclepiusSerpent" x1="20" y1="20" x2="80" y2="85" gradientUnits="userSpaceOnUse">
                          <stop offset="0%" stop-color="#e0f2fe"/>
                          <stop offset="40%" stop-color="#38bdf8"/>
                          <stop offset="80%" stop-color="#0ea5e9"/>
                          <stop offset="100%" stop-color="#818cf8"/>
                        </linearGradient>
                        <filter id="neonStaffGlow" x="-30%" y="-30%" width="160%" height="160%">
                          <feGaussianBlur stdDeviation="2.5" result="blur"/>
                          <feMerge>
                            <feMergeNode in="blur"/>
                            <feMergeNode in="SourceGraphic"/>
                          </feMerge>
                        </filter>
                      </defs>
                      <line x1="50" y1="14" x2="50" y2="86" stroke="url(#asclepiusStaff)" stroke-width="4.5" stroke-linecap="round" filter="url(#neonStaffGlow)"/>
                      <circle cx="50" cy="14" r="5" fill="#ffffff" filter="url(#neonStaffGlow)"/>
                      <circle cx="50" cy="86" r="3" fill="#38bdf8"/>
                      <path d="M 48,22 C 32,25 31,37 50,40 C 69,43 68,55 50,58 C 32,61 31,73 50,76 C 59,77.5 61,82 52,85" 
                            stroke="url(#asclepiusSerpent)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" fill="none" filter="url(#neonStaffGlow)"/>
                      <circle cx="50" cy="22" r="3.2" fill="#e0f2fe"/>
                      <circle cx="51.5" cy="21.5" r="1" fill="#0284c7"/>
                      <path d="M 50,33 L 50,37 M 48,35 L 52,35" stroke="#ffffff" stroke-width="1.5" stroke-linecap="round" opacity="0.9"/>
                      <path d="M 50,69 L 50,73 M 48,71 L 52,71" stroke="#ffffff" stroke-width="1.5" stroke-linecap="round" opacity="0.9"/>
                    </svg>
                </div>
            </div>
            
            <h1 class="splash-title">Prescript Cloud</h1>
            <p class="splash-subtitle">Iniciando Core do Sistema</p>
            
            <div class="splash-progress-container">
                <div class="splash-bar-wrap">
                    <div class="splash-bar-fill" id="overdrive-bar"></div>
                </div>
                <div class="splash-percent-readout" id="overdrive-percent">0%</div>
            </div>
            
            <div class="splash-status" id="overdrive-text">Autenticando...</div>
            
            <div class="splash-skip-hint" id="overdrive-skip-btn">
                <span class="skip-hint-dot"></span>
                <span class="skip-key-badge">ESC</span> ou toque para pular
            </div>
        </div>
    `;
    document.body.appendChild(splash);

    const loginScreen = document.getElementById('login-screen');
    if(loginScreen) loginScreen.style.opacity = '0';

    const bar = document.getElementById('overdrive-bar');
    const percent = document.getElementById('overdrive-percent');
    const text = document.getElementById('overdrive-text');

    // GERADOR DE PARTÍCULAS CIRCULARES SUAVES
    let isSkipped = false;
    let sparkInterval = setInterval(() => {
        if (isSkipped) return;
        const spark = document.createElement('div');
        spark.className = 'data-spark';
        const size = Math.floor(Math.random() * 4) + 3;
        spark.style.width = size + 'px';
        spark.style.height = size + 'px';
        spark.style.left = (Math.random() * 92 + 4) + 'vw';
        spark.style.bottom = '-10px';
        spark.style.animationDuration = (Math.random() * 1.5 + 1.6) + 's';
        splash.appendChild(spark);
        setTimeout(() => spark.remove(), 3200); 
    }, 160);

    // FUNÇÃO DE ATUALIZAÇÃO COM MICRO CROSS-FADE
    const updateStatus = (newText, newColor, isSuccess) => {
        if (!text) return;
        text.style.opacity = '0';
        text.style.transform = 'translateY(3px)';
        setTimeout(() => {
            text.innerText = newText;
            if (newColor) text.style.color = newColor;
            if (isSuccess) {
                text.style.textShadow = '0 0 16px #38bdf8, 0 0 30px rgba(56, 189, 248, 0.7)';
            }
            text.style.opacity = '1';
            text.style.transform = 'translateY(0)';
        }, 140);
    };

    // FAST-SKIP INTERATIVO (UX MÉDICA DE ELITE)
    const triggerSkip = () => {
        if (isSkipped) return;
        isSkipped = true;

        clearTimeout(timer1);
        clearTimeout(timer2);
        clearTimeout(timer3);
        clearTimeout(timer4);
        clearInterval(sparkInterval);

        window.removeEventListener('keydown', handleKeySkip);
        splash.removeEventListener('click', triggerSkip);

        if (bar) {
            bar.style.transition = 'width 0.2s cubic-bezier(0.16, 1, 0.3, 1)';
            bar.style.width = '100%';
        }
        if (percent) percent.innerText = '100%';
        
        updateStatus('SISTEMA ONLINE', '#38bdf8', true);

        setTimeout(() => {
            splash.classList.add('zoom-out');
            if(loginScreen) loginScreen.style.opacity = '1';
            setTimeout(() => splash.remove(), 800);
        }, 220);
    };

    const handleKeySkip = (e) => {
        if (e.key === 'Escape' || e.key === ' ' || e.key === 'Enter' || !e.repeat) {
            triggerSkip();
        }
    };

    window.addEventListener('keydown', handleKeySkip, { once: true });
    splash.addEventListener('click', triggerSkip);

    // CRONOGRAMA AUTOMÁTICO SE NÃO PULAR
    const timer1 = setTimeout(() => { 
        if (isSkipped) return;
        if (bar) bar.style.width = '38%'; 
        if (percent) percent.innerText = '38%';
        updateStatus('Sincronizando Banco de Dados...'); 
    }, 450);

    const timer2 = setTimeout(() => { 
        if (isSkipped) return;
        if (bar) bar.style.width = '82%'; 
        if (percent) percent.innerText = '82%';
        updateStatus('Criptografia Quântica Ativa...'); 
    }, 1100);

    const timer3 = setTimeout(() => { 
        if (isSkipped) return;
        if (bar) bar.style.width = '100%'; 
        if (percent) percent.innerText = '100%';
        updateStatus('SISTEMA ONLINE', '#38bdf8', true);
        
        clearInterval(sparkInterval);
        for(let i = 0; i < 15; i++){
            let s = document.createElement('div');
            s.className = 'data-spark'; 
            s.style.left = (Math.random() * 90 + 5) + 'vw';
            s.style.bottom = '10px';
            s.style.animationDuration = '0.9s'; 
            s.style.width = '5px';
            s.style.height = '5px';
            s.style.background = '#fff';
            splash.appendChild(s);
        }
    }, 1750);

    const timer4 = setTimeout(() => {
        if (isSkipped) return;
        window.removeEventListener('keydown', handleKeySkip);
        splash.classList.add('zoom-out');
        if(loginScreen) loginScreen.style.opacity = '1';
        setTimeout(() => splash.remove(), 1000);
    }, 2350);
};

// Executa a sequência
window.addEventListener('load', () => {
    App.playOverdriveBootSequence();
});
