// 🛡️ A SOLUÇÃO ABSOLUTA: O BOTÃO "DESVIA-SE" DA LISTA
// =========================================================================
setTimeout(() => {
    // Um radar super rápido que verifica a posição da lista 20 vezes por segundo
    setInterval(() => {
        const dropdown = document.getElementById('med-dropdown');
        const addBtn = document.getElementById('add-btn');
        
        if (dropdown && addBtn) {
            // Verifica se a lista suspensa está aberta e com resultados visíveis
            const isDropdownOpen = dropdown.style.display === 'block' || (dropdown.style.display !== 'none' && dropdown.innerHTML.trim() !== '');
            
            if (isDropdownOpen) {
                // Se a lista abriu, "esmaga" e apaga temporariamente o botão azul
                addBtn.style.setProperty('z-index', '-10', 'important');
                addBtn.style.setProperty('opacity', '0.1', 'important');
                addBtn.style.setProperty('pointer-events', 'none', 'important');
                addBtn.style.setProperty('animation', 'none', 'important'); // Desliga o pulso que furava a lista
                addBtn.style.setProperty('transform', 'scale(0.95)', 'important');
                addBtn.style.setProperty('transition', 'all 0.2s ease', 'important');
            } else {
                // Quando a lista fecha (remédio selecionado), o botão volta à vida instantaneamente
                addBtn.style.removeProperty('z-index');
                addBtn.style.removeProperty('opacity');
                addBtn.style.removeProperty('pointer-events');
                addBtn.style.removeProperty('animation');
                addBtn.style.removeProperty('transform');
            }
        }
    }, 50);
}, 3000); // Aguarda a página carregar por completo para iniciar o radar
