// 🤖 ROBÔ INVISÍVEL: AUTO-CORRETOR DE Z-INDEX E DATA (RODA EM BACKGROUND)
// =========================================================================
setInterval(() => {
    // 1. Z-INDEX: Força a Gaveta do Prontuário a ficar acima de tudo (Camada Máxima)
    const prontuario = document.getElementById('prontuario-drawer');
    if (prontuario && prontuario.style.zIndex !== '2147483647') {
        prontuario.style.setProperty('z-index', '2147483647', 'important');
    }
    
    // Força o Botão de Perfil a ficar numa camada muito inferior
    const perfil = document.getElementById('top-profile-module');
    if (perfil && perfil.style.zIndex !== '1000') {
        perfil.style.setProperty('z-index', '1000', 'important');
    }

    // 2. A MÁGICA DA DATA: Lê o seu botão de configurações original
    if (window.App && window.App.config && window.App.config.onlyFirstDate) {
        // Pega todas as folhas geradas na tela
        const paginas = document.querySelectorAll('.a4-page');
        
        paginas.forEach(pagina => {
            // Conta os quadrantes (as 4 vias) dentro da folha
            const vias = pagina.querySelectorAll('.quadrante');
            
            if (vias.length === 4) {
                // Deixa a via 0 (primeira) em paz. Altera apenas a 1, 2 e 3 (Cópias)
                for (let i = 1; i < 4; i++) {
                    const caixaData = vias[i].querySelector('.date-right');
                    // Se a data já não estiver com tracinhos, ele substitui
                    if (caixaData && !caixaData.innerText.includes('_____/_____/______')) {
                        caixaData.innerHTML = 'Feira de Santana, _____/_____/______';
                    }
                }
            }
        });
    }
}, 500); // O robô vigia a tela a cada meio segundo
