// 🚨 PATCH V43: BOTÕES EMPILHADOS (UM EMBAIXO DO OUTRO) + MÓDULO SOS
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {
        
        // 1. ARRUMA O LAYOUT: COLOCA OS BOTÕES NUMA CAIXA VERTICAL
        const addBtn = document.getElementById('add-btn');
        if (addBtn && !document.getElementById('action-buttons-wrapper-v2')) {

            // Remove o wrapper antigo (se existir) para evitar duplicação
            const oldWrapper = document.getElementById('action-buttons-wrapper');
            if (oldWrapper) {
                oldWrapper.parentNode.insertBefore(addBtn, oldWrapper);
                oldWrapper.remove();
            }

            // Cria a nova caixa flexível VERTICAL
            const btnContainer = document.createElement('div');
            btnContainer.id = 'action-buttons-wrapper-v2';
            btnContainer.style.display = 'flex';
            btnContainer.style.flexDirection = 'column'; // 👈 O segredo: empilha os itens!
            btnContainer.style.gap = '10px';
            btnContainer.style.width = '100%';
            btnContainer.style.marginTop = '15px';

            // Insere a caixa e move o botão azul para dentro dela
            addBtn.parentNode.insertBefore(btnContainer, addBtn);
            btnContainer.appendChild(addBtn);

            // Formata o botão azul para ocupar 100% da largura da linha
            addBtn.style.width = '100%';
            addBtn.style.margin = '0';
            addBtn.style.padding = '15px';
            addBtn.style.fontSize = '15px';
            addBtn.style.whiteSpace = 'normal';
            addBtn.style.lineHeight = '1.2';
            addBtn.style.borderRadius = '12px';

            // Cria o botão vermelho SOS
            const sosBtn = document.createElement('button');
            sosBtn.id = 'btn-sos-module';
            sosBtn.innerHTML = '🚨 SOS / CONTENÇÃO';
            sosBtn.style.cssText = `
                display: none; /* Escondido por padrão */
                width: 100%; /* Ocupa 100% da largura */
                background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%) !important;
                color: #ffffff !important; border: none !important;
                padding: 15px !important; border-radius: 12px !important;
                font-size: 15px !important; font-weight: 900 !important;
                text-transform: uppercase !important; letter-spacing: 0.5px !important;
                box-shadow: 0 8px 25px rgba(239, 68, 68, 0.4) !important;
                cursor: pointer !important; transition: all 0.3s ease !important;
                margin: 0 !important;
                white-space: normal !important;
                line-height: 1.2 !important;
            `;
            sosBtn.onclick = (e) => { e.preventDefault(); App.openSOSModal(); };

            // Coloca o botão vermelho na caixa (abaixo do azul)
            btnContainer.appendChild(sosBtn);
        }

        // 2. MODAL DE PROTOCOLOS (Mantido intacto)
        App.openSOSModal = function() {
            let modal = document.getElementById('sos-modal-pro');
            if (modal) modal.remove();
            modal = document.createElement('div');
            modal.id = 'sos-modal-pro';
            modal.style.cssText = 'position: fixed; inset: 0; background: rgba(15, 23, 42, 0.9); backdrop-filter: blur(10px); z-index: 100005; display: flex; align-items: center; justify-content: center; animation: entFadeIn 0.2s forwards;';
            modal.innerHTML = `
                <div style="background: #0f172a; border: 1px solid #ef4444; border-radius: 16px; width: 600px; max-width: 95vw; padding: 30px; box-shadow: 0 25px 50px rgba(0,0,0,0.5); font-family: 'Inter', sans-serif;">
                    <h2 style="color: #ef4444; margin: 0 0 15px 0; font-size: 1.5rem; font-weight: 800; display: flex; align-items: center; gap: 10px;">🚨 Protocolos de Emergência</h2>
                    <div style="display: flex; flex-direction: column; gap: 15px; margin-bottom: 25px;">
                        <label style="display: flex; align-items: flex-start; gap: 12px; cursor: pointer; background: rgba(255,255,255,0.03); padding: 15px; border-radius: 10px; border: 1px solid #334155;">
                            <input type="checkbox" id="chk-sos-1" value="SE APM, HALOPERIDOL DECANOATO 50MG/ML + FENERGAM 25MG/ML, AMBOS 01 AMPOLA POR VIA INTRAMUSCULAR; ATÉ 3X/DIA." style="width: 20px; height: 20px;">
                            <span style="color: #f8fafc; font-weight: 600; font-size: 0.9rem;">HALOPERIDOL + FENERGAM (SOS APM)</span>
                        </label>
                        <label style="display: flex; align-items: flex-start; gap: 12px; cursor: pointer; background: rgba(255,255,255,0.03); padding: 15px; border-radius: 10px; border: 1px solid #334155;">
                            <input type="checkbox" id="chk-sos-2" value="CONTENÇÃO MECÂNICA DE ATÉ 2 HORAS SE NECESSÁRIO." style="width: 20px; height: 20px;">
                            <span style="color: #f8fafc; font-weight: 600; font-size: 0.9rem;">CONTENÇÃO MECÂNICA (ATÉ 2H)</span>
                        </label>
                    </div>
                    <textarea id="txt-sos-custom" placeholder="Conduta personalizada..." style="width: 100%; height: 80px; background: #0b1120; border: 1px solid #334155; color: #fff; padding: 12px; border-radius: 8px; outline: none; resize: none;"></textarea>
                    <div style="display: flex; gap: 12px; margin-top: 25px;">
                        <button onclick="document.getElementById('sos-modal-pro').remove()" style="flex: 1; padding: 15px; background: transparent; border: 1px solid #334155; color: #cbd5e1; border-radius: 10px; cursor: pointer; font-weight: 700;">Cancelar</button>
                        <button onclick="App.addSOSToPrescription()" style="flex: 1.5; padding: 15px; background: #ef4444; border: none; color: #fff; border-radius: 10px; cursor: pointer; font-weight: 700;">Incluir na Prescrição</button>
                    </div>
                </div>
            `;
            document.body.appendChild(modal);
        };

        App.addSOSToPrescription = function() {
            const chk1 = document.getElementById('chk-sos-1');
            const chk2 = document.getElementById('chk-sos-2');
            const custom = document.getElementById('txt-sos-custom');
            if (chk1?.checked) this.items.push({ med: chk1.value, poso: "", usage: "SOS", data: { type: 'SOS' } });
            if (chk2?.checked) this.items.push({ med: chk2.value, poso: "", usage: "CONDUTA", data: { type: 'SOS' } });
            if (custom?.value.trim()) this.items.push({ med: custom.value.trim().toUpperCase(), poso: "", usage: "SOS", data: { type: 'SOS' } });
            this.render();
            document.getElementById('sos-modal-pro').remove();
        };

        // 3. A MÁGICA DA VISIBILIDADE NO RENDER
        const originalRender = App.render;
        App.render = function() {
            originalRender.apply(this);

            const prescPages = Math.ceil(this.items.length / 5) || 1;
            const hasLME = this.lmeData && this.lmeData.active;
            const lmePages = hasLME ? (this.groupHighCostItems(this.lmeData.items) ? Object.keys(this.groupHighCostItems(this.lmeData.items)).length * 2 : 0) : 0;
            const examPages = (this.selectedExams && this.selectedExams.size > 0) ? 1 : 0;
            
            const wardStartIndex = prescPages + lmePages + examPages;
            
            const sosBtn = document.getElementById('btn-sos-module');
            if (sosBtn) {
                const isOnWardPage = this.includeWardSheet && (this.currentPage >= wardStartIndex);
                
                if (isOnWardPage) {
                    sosBtn.style.display = 'block'; // 👈 Agora aparece como um bloco inteiro
                } else {
                    sosBtn.style.display = 'none';
                }
            }
        };

        if (App.items) App.render();
    }
}, 9000);
// =========================================================================
// 🌟 PATCH V45: ORDENAÇÃO AUTOMÁTICA SOS + ISOLAMENTO + CORREÇÃO DE SOBREPOSIÇÃO
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {
        
        // 1. CSS PARA GARANTIR A QUEBRA DE LINHA CORRETA
        let style = document.getElementById('ward-text-wrap-fix');
        if (!style) {
            style = document.createElement('style');
            style.id = 'ward-text-wrap-fix';
            document.head.appendChild(style);
        }
        style.innerHTML = `.ward-item-text { white-space: normal !important; }`;

        // 2. REESCREVEMOS O RENDER PRINCIPAL PARA ORGANIZAR AS REGRAS
        App.render = function() {
            
            // MÁGICA 1: Deteta qualquer SOS (mesmo digitado à mão) e etiqueta-o!
            this.items.forEach(it => {
                if (it.med && it.med.match(/\b(SOS|CONTENÇÃO|CONTENCAO|SE APM|MECÂNICA|MECANICA)\b/i)) {
                    if (!it.data) it.data = {};
                    it.data.type = 'SOS';
                }
            });

            // MÁGICA 2: Sorteia a lista -> Normais primeiro, SOS sempre no final!
            const normals = this.items.filter(it => !(it.data && it.data.type === 'SOS'));
            const soses = this.items.filter(it => it.data && it.data.type === 'SOS');
            this.items = [...normals, ...soses]; // Salva a ordem corrigida

            // Atualiza a lista na tela (já ordenada com SOS no fim)
            if (this.DOM.uiList) {
                this.DOM.uiList.innerHTML = this.items.map((it, i) => `<div class="item-row" draggable="true" data-index="${i}" oncontextmenu="App.showContextMenu(event, ${i})"><div class="item-row-content"><span>${it.med}</span><div class="row-actions"><button class="btn-icon" onclick="App.loadItemForEdit(${i})" title="Editar">✏️</button><button class="btn-icon btn-del" onclick="App.items.splice(${i},1);App.render()" title="Remover">×</button></div></div></div>`).join(''); 
            }

            const btnBatch = document.getElementById('btn-batch-lme'); 
            if(btnBatch) btnBatch.classList.toggle('hidden', !this.items.some(item => this.isHighCost(item.med))); 

            if(this.DOM.outputContainer) this.DOM.outputContainer.innerHTML = ""; 
            
            let groupedHighCost = {}; 
            if (this.lmeData && this.lmeData.active) { groupedHighCost = this.groupHighCostItems(this.lmeData.items); } 
            const hasLME = Object.keys(groupedHighCost).length > 0;
            
            // MATEMÁTICA: A Receita Comum só conta as páginas baseada nos remédios NORMAIS (Ignora o SOS)
            let totalPagesPrescription = Math.ceil(normals.length / 5); 
            const hasExams = this.selectedExams && this.selectedExams.size > 0;
            
            let wardPagesCount = 0;
            if (this.includeWardSheet) {
                wardPagesCount = Math.max(1, Math.ceil(this.items.length / 9)); // Internamento usa TODOS
            }
            
            if (totalPagesPrescription === 0 && !hasExams && !hasLME && wardPagesCount === 0) { totalPagesPrescription = 1; }
            
            const totalPages = totalPagesPrescription + (Object.keys(groupedHighCost).length * 2) + (hasExams ? 1 : 0) + wardPagesCount; 
            if (this.currentPage >= totalPages) this.currentPage = totalPages > 0 ? totalPages - 1 : 0; 
            
            // MÁGICA 3: Oculta temporariamente os SOS da Receita Comum!
            const originalItems = this.items;
            this.items = normals; // Passa apenas os comprimidos para a receita de pé
            
            for (let p = 0; p < totalPagesPrescription; p++) { 
                if (this.pageDateStates[p] === undefined) this.pageDateStates[p] = false; 
                this.renderPrescriptionPage(p, totalPagesPrescription, this.pageDateStates[p]); 
            } 
            
            this.items = originalItems; // Restaura tudo para poder gerar o Internamento completo!
            
            let indexOffset = totalPagesPrescription;
            
            if (hasLME) { 
                Object.keys(groupedHighCost).forEach(groupName => { 
                    if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = true; 
                    this.renderSixMonthRecipe(groupedHighCost[groupName], indexOffset, this.pageDateStates[indexOffset]); 
                    if (this.pageDateStates[indexOffset + 1] === undefined) this.pageDateStates[indexOffset + 1] = true; 
                    this.renderLMEPage(groupedHighCost[groupName], groupName, indexOffset + 1, this.pageDateStates[indexOffset + 1]); 
                    indexOffset += 2; 
                }); 
            } 
            
            if (hasExams) { this.renderExamsPage(indexOffset); indexOffset += 1; }

            if (wardPagesCount > 0) {
                for (let wp = 0; wp < wardPagesCount; wp++) {
                    this.renderWardPage(indexOffset, wp);
                    indexOffset += 1;
                }
            }

            // Visibilidade do botão vermelho SOS
            const sosBtn = document.getElementById('btn-sos-module');
            if (sosBtn) {
                const trueWardStart = totalPagesPrescription + (hasLME ? Object.keys(groupedHighCost).length * 2 : 0) + (hasExams ? 1 : 0);
                const isOnWardPage = this.includeWardSheet && (this.currentPage >= trueWardStart);
                sosBtn.style.display = isOnWardPage ? 'block' : 'none';
            }
            
            // Controles de Navegação de Página
            const navControls = document.getElementById('nav-controls'); if(navControls) navControls.classList.remove('hidden'); 
            const pageInd = document.getElementById('page-indicator'); if(pageInd) pageInd.innerText = `Página ${this.currentPage + 1} de ${totalPages || 1}`; 
            const prevPage = document.getElementById('prev-page'); if(prevPage) prevPage.disabled = this.currentPage === 0; 
            const nextPage = document.getElementById('next-page'); if(nextPage) nextPage.disabled = this.currentPage >= (totalPages || 1) - 1; 
            if (window.updatePageNavPills) window.updatePageNavPills();
            if(this.DOM.dateCheck) this.DOM.dateCheck.checked = !!this.pageDateStates[this.currentPage];

            // Sincroniza o número do prontuário
            setTimeout(() => {
                const syncInputs = document.querySelectorAll('.sync-pront-all');
                syncInputs.forEach(inp => {
                    inp.addEventListener('input', (e) => {
                        syncInputs.forEach(other => { 
                            if (other !== inp) {
                                other.value = e.target.value;
                                other.setAttribute('value', e.target.value);
                            }
                        });
                    });
                });
            }, 100);
        };

        // 3. CORRIGE A RENDERIZAÇÃO DA FOLHA DE INTERNAMENTO (ADEUS SOBREPOSIÇÃO)
        App.renderWardPage = function(globalPageIndex, wardPageIndex = 0) {
            const isHidden = globalPageIndex !== this.currentPage ? 'hidden' : '';
            const patientName = document.getElementById('patient-name')?.value.toUpperCase() || '';
            const signature = (this.config && this.config.signature) ? `<img src="${this.config.signature}" style="position:absolute; bottom:6.5%; left:14%; max-width:250px; max-height:80px; object-fit:contain; z-index:5;">` : '';

            const today = new Date();
            const dd = String(today.getDate()).padStart(2, '0');
            const mm = String(today.getMonth() + 1).padStart(2, '0');
            const yyyy = today.getFullYear();

            const formatNum = (val) => { 
                let v = parseFloat(val) || 0;
                if (v === 0) return "00";
                if (v < 10 && Number.isInteger(v)) return "0" + v;
                if (v === 0.25) return "1/4"; if (v === 0.5) return "1/2"; if (v === 0.75) return "3/4";
                return v.toString().replace('.', ',');
            };

            let medRows = '';
            const startY = 41; 
            const stepY = 4.5; 

            const itemsSlice = this.items.slice(wardPageIndex * 9, (wardPageIndex * 9) + 9);

            itemsSlice.forEach((item, index) => {
                const y = startY + (index * stepY);
                let medName = item.med.toUpperCase().replace(/\s*\(\s*(COMP|GOTAS\/ML|AMP\/INJ|COMPRIMIDOS?|GOTAS|AMPOLAS?)\s*\)\s*$/i, '');
                
                const isSOS = (item.data && item.data.type === 'SOS');

                if (isSOS) {
                    // MÁGICA 4: SOS com fonte fina (11.5px) e compacta para não bater nas linhas vizinhas!
                    medRows += `
                        <div class="ward-item-text" style="top: ${y}%; left: 6.8%; width: 85%; display: flex; align-items: center;">
                            <span style="font-size: 11.5px; font-weight: 800; color: #000; line-height: 1.1;">${item.med}</span>
                        </div>
                    `;
                } else {
                    const isInject = (item.data && item.data.type === 'INJECT') || medName.match(/\b(INJ|INJET[AÁ]VEL|AMPOLA|DECANOATO)\b/i);

                    if (isInject) {
                        const qty = parseFloat(item.data?.m) || 0;
                        const days = parseFloat(item.data?.t) || 0;
                        const ampLabel = qty > 1 ? "AMPOLAS" : "AMPOLA";
                        
                        let via = "INTRAMUSCULAR";
                        if (medName.match(/\bIV\b|\bEV\b|\bINTRAVENOSA\b/i)) via = "INTRAVENOSA";
                        else if (medName.match(/\bSC\b|\bSUBCUT[AÂ]NEA\b/i)) via = "SUBCUTÂNEA";

                        let posoInject = `USO: ${formatNum(qty)} ${ampLabel} POR VIA ${via} A CADA ${formatNum(days)} DIAS.`;

                        // MÁGICA 5: Injetável com fonte levemente menor (12.5px) para as 2 linhas caberem com folga
                        medRows += `
                            <div class="ward-item-text" style="top: ${y}%; left: 6.8%; width: 44%; display: flex; flex-direction: column; align-items: flex-start; justify-content: center;">
                                <span style="font-size: 12.5px; font-weight: 900; color: #000; line-height: 1.1;">${medName}</span>
                                <span style="font-size: 10px; font-weight: normal; color: #000; margin-top: 1px;">${posoInject}</span>
                            </div>
                        `;
                    } else {
                        let m = formatNum(item.data?.m); let t = formatNum(item.data?.t); let n = formatNum(item.data?.n);
                        let posoCompacta = `${m} &nbsp;&nbsp;-&nbsp;&nbsp; ${t} &nbsp;&nbsp;-&nbsp;&nbsp; ${n}`;

                        // Comprimidos e Gotas mantêm o formato poderoso e grande
                        medRows += `
                            <div class="ward-item-text" style="top: ${y}%; left: 6.8%; width: 45%; display: flex; justify-content: space-between; align-items: center; padding-right: 10px;">
                                <span style="font-size: 13.5px; font-weight: 900; color: #000; max-width: 250px; line-height: 1.1;">${medName}</span>
                                <span style="font-size: 15px; font-weight: 900; color: #000; letter-spacing: 1px; white-space: nowrap;">${posoCompacta}</span>
                            </div>
                        `;
                    }
                }
            });

            // As suas coordenadas perfeitas!
            const posDia = "18.5%";  
            const posMes = "22.5%";  
            const posAno = "26.0%";  

            const fullHtml = `
                <div class="ward-print-wrapper ${isHidden}">
                    <div class="ward-landscape-page">
                        <img src="PRESCRIÇÃO MÉDICA ATUALIZADA_page-0001.jpg" class="ward-bg-img">
                        <div style="position:absolute; z-index:10; font-weight:900; font-size:22px; color:black; top:16.0%; left:10.5%; width:58%; text-transform:uppercase;">${patientName}</div>
                        <input type="text" class="ward-prontuario-input sync-pront-all" style="position:absolute; z-index:999 !important; top:16.0%; left:81%; width:15%; border:none; background:transparent; font-size:22px; font-weight:900; color:#000 !important; text-align:center; outline:none;" placeholder="---">
                        
                        ${medRows}
                        ${signature}
                        
                        <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posDia};">${dd}</div>
                        <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posMes};">${mm}</div>
                        <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posAno};">${yyyy}</div>
                    </div>
                </div>
            `;
            if (this.DOM.outputContainer) this.DOM.outputContainer.insertAdjacentHTML('beforeend', fullHtml);
        };

        if (App.items) App.render();
    }
}, 9500);
// =========================================================================
// 🌟 PATCH V57: DATA NA ABA "USUÁRIOS" + MESTRE ABSOLUTO
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {
        
        // 1. CSS GERAL E GRELHA ANTI-SOBREPOSIÇÃO
        let style = document.getElementById('ward-text-wrap-fix');
        if (!style) {
            style = document.createElement('style');
            style.id = 'ward-text-wrap-fix';
            document.head.appendChild(style);
        }
        style.innerHTML = `.ward-item-text { white-space: normal !important; }`;

        // 2. INJETOR EXCLUSIVO PARA A ABA DE USUÁRIOS NO MENU DE CONFIGURAÇÕES
        setInterval(() => {
            try {
                // Procura o Modal de Configurações aberto
                const configModal = document.getElementById('config-modal') || document.querySelector('.config-modal') || document.getElementById('settings-modal');
                
                if (configModal && configModal.style.display !== 'none' && !document.getElementById('auto-date-config-wrapper')) {
                    
                    // Procura especificamente a aba ou sessão de "Usuários"
                    // (Tenta por IDs comuns que você possa ter usado)
                    let targetTab = document.getElementById('tab-user') || 
                                    document.getElementById('config-usuarios') || 
                                    document.getElementById('usuarios') || 
                                    document.getElementById('user-settings');
                    
                    // Se não achar por ID, procura a div que contenha o texto "Usuário" ou "CRM"
                    if (!targetTab) {
                        const sections = configModal.querySelectorAll('div, section, form');
                        targetTab = Array.from(sections).find(el => {
                            const txt = el.textContent.toLowerCase();
                            return (txt.includes('usuário') || txt.includes('usuario') || txt.includes('dados do médico')) && el.children.length > 0;
                        });
                    }

                    // Se por algum motivo não achar a aba de usuários, joga no corpo do modal
                    const finalTarget = targetTab || configModal.querySelector('.modal-body') || configModal.querySelector('form') || configModal;

                    const wrapper = document.createElement('div');
                    wrapper.id = 'auto-date-config-wrapper';
                    // Estilo idêntico a opções de formulário profissionais
                    wrapper.style.cssText = 'margin-top: 15px; padding: 10px 15px; background: rgba(255,255,255,0.05); border-radius: 8px; border: 1px solid #334155; display: flex; align-items: center; gap: 10px; width: 100%; box-sizing: border-box;';
                    
                    const isChecked = localStorage.getItem('cerebrum_auto_date') !== 'false' ? 'checked' : '';
                    
                    wrapper.innerHTML = `
                        <input type="checkbox" id="chk-auto-date-config" ${isChecked} style="width: 18px; height: 18px; cursor: pointer; margin: 0; accent-color: #3b82f6;">
                        <label for="chk-auto-date-config" style="color: inherit; cursor: pointer; font-size: 14px; font-weight: 600; margin: 0;">
                            🗓️ Ativar "Data" por padrão em novas receitas
                        </label>
                    `;

                    // Salva na memória do navegador na mesma hora que você clica
                    wrapper.querySelector('input').addEventListener('change', (e) => {
                        localStorage.setItem('cerebrum_auto_date', e.target.checked ? 'true' : 'false');
                    });

                    finalTarget.appendChild(wrapper);
                }
            } catch(e) {}
        }, 1500); // Roda a cada 1.5s no fundo sem pesar o sistema

        // 3. RECONSTRUÇÃO DO LAYOUT DE BOTÕES (TELA PRINCIPAL)
        const addBtn = document.getElementById('add-btn');
        
        if (addBtn && !document.getElementById('master-btn-container')) {
            const oldGrid = document.getElementById('action-buttons-grid');
            if (oldGrid) { oldGrid.parentNode.insertBefore(addBtn, oldGrid); oldGrid.remove(); }
            const oldWrapper = document.getElementById('action-buttons-wrapper-v2');
            if (oldWrapper) { oldWrapper.parentNode.insertBefore(addBtn, oldWrapper); oldWrapper.remove(); }

            let cancelBtn = document.getElementById('cancel-btn') || document.getElementById('btn-cancel');
            if (!cancelBtn) {
                cancelBtn = Array.from(addBtn.parentNode.children).find(el => el.tagName === 'BUTTON' && el.textContent.toUpperCase().includes('CANCEL'));
            }

            const masterContainer = document.createElement('div');
            masterContainer.id = 'master-btn-container';
            masterContainer.style.display = 'flex';
            masterContainer.style.flexDirection = 'column';
            masterContainer.style.gap = '10px';
            masterContainer.style.width = '100%';
            masterContainer.style.marginTop = '15px';

            const topRow = document.createElement('div');
            topRow.id = 'top-btn-row';
            topRow.style.display = 'flex';
            topRow.style.gap = '10px';
            topRow.style.width = '100%';

            addBtn.parentNode.insertBefore(masterContainer, addBtn);
            
            topRow.appendChild(addBtn);
            if (cancelBtn) topRow.appendChild(cancelBtn);
            
            masterContainer.appendChild(topRow);

            addBtn.style.flex = '1'; addBtn.style.margin = '0'; addBtn.style.padding = '15px';
            addBtn.style.borderRadius = '12px'; addBtn.style.fontSize = '14px'; addBtn.style.fontWeight = 'bold';

            if (cancelBtn) {
                cancelBtn.style.flex = '1'; cancelBtn.style.margin = '0'; cancelBtn.style.padding = '15px';
                cancelBtn.style.borderRadius = '12px'; cancelBtn.style.fontSize = '14px';
                cancelBtn.style.fontWeight = 'bold'; cancelBtn.style.whiteSpace = 'nowrap';
            }

            // O Botão de SOS fica limpo!
            const sosBtn = document.createElement('button');
            sosBtn.id = 'btn-sos-module';
            sosBtn.innerHTML = '🚨 SOS / CONTENÇÃO';
            sosBtn.style.cssText = `
                display: none; width: 100%;
                background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%) !important;
                color: #ffffff !important; border: none !important;
                padding: 15px !important; border-radius: 12px !important;
                font-size: 15px !important; font-weight: 900 !important;
                text-transform: uppercase !important; letter-spacing: 0.5px !important;
                box-shadow: 0 8px 25px rgba(239, 68, 68, 0.4) !important;
                cursor: pointer !important; transition: all 0.3s ease !important;
                margin: 0 !important; white-space: normal !important; line-height: 1.2 !important;
            `;
            sosBtn.onclick = (e) => { e.preventDefault(); App.openSOSModal(); };
            
            masterContainer.appendChild(sosBtn);
        }

        // 4. MODAL DE EMERGÊNCIA
        App.openSOSModal = function() {
            let modal = document.getElementById('sos-modal-pro');
            if (modal) modal.remove();
            modal = document.createElement('div');
            modal.id = 'sos-modal-pro';
            modal.style.cssText = 'position: fixed; inset: 0; background: rgba(15, 23, 42, 0.9); backdrop-filter: blur(10px); z-index: 100005; display: flex; align-items: center; justify-content: center; animation: entFadeIn 0.2s forwards;';
            modal.innerHTML = `
                <div style="background: #0f172a; border: 1px solid #ef4444; border-radius: 16px; width: 600px; max-width: 95vw; padding: 30px; box-shadow: 0 25px 50px rgba(0,0,0,0.5); font-family: 'Inter', sans-serif;">
                    <h2 style="color: #ef4444; margin: 0 0 15px 0; font-size: 1.5rem; font-weight: 800; display: flex; align-items: center; gap: 10px;">🚨 Protocolos de Emergência</h2>
                    <div style="display: flex; flex-direction: column; gap: 15px; margin-bottom: 25px;">
                        <label style="display: flex; align-items: flex-start; gap: 12px; cursor: pointer; background: rgba(255,255,255,0.03); padding: 15px; border-radius: 10px; border: 1px solid #334155;">
                            <input type="checkbox" id="chk-sos-1" value="SE APM, HALOPERIDOL DECANOATO 50MG/ML + FENERGAM 25MG/ML, AMBOS 01 AMPOLA POR VIA INTRAMUSCULAR; ATÉ 3X/DIA." style="width: 20px; height: 20px;">
                            <span style="color: #f8fafc; font-weight: 600; font-size: 0.9rem;">HALOPERIDOL + FENERGAM (SOS APM)</span>
                        </label>
                        <label style="display: flex; align-items: flex-start; gap: 12px; cursor: pointer; background: rgba(255,255,255,0.03); padding: 15px; border-radius: 10px; border: 1px solid #334155;">
                            <input type="checkbox" id="chk-sos-2" value="CONTENÇÃO MECÂNICA DE ATÉ 2 HORAS SE NECESSÁRIO." style="width: 20px; height: 20px;">
                            <span style="color: #f8fafc; font-weight: 600; font-size: 0.9rem;">CONTENÇÃO MECÂNICA (ATÉ 2H)</span>
                        </label>
                    </div>
                    <textarea id="txt-sos-custom" placeholder="Conduta personalizada..." style="width: 100%; height: 80px; background: #0b1120; border: 1px solid #334155; color: #fff; padding: 12px; border-radius: 8px; outline: none; resize: none;"></textarea>
                    <div style="display: flex; gap: 12px; margin-top: 25px;">
                        <button onclick="document.getElementById('sos-modal-pro').remove()" style="flex: 1; padding: 15px; background: transparent; border: 1px solid #334155; color: #cbd5e1; border-radius: 10px; cursor: pointer; font-weight: 700;">Cancelar</button>
                        <button onclick="App.addSOSToPrescription()" style="flex: 1.5; padding: 15px; background: #ef4444; border: none; color: #fff; border-radius: 10px; cursor: pointer; font-weight: 700;">Incluir na Prescrição</button>
                    </div>
                </div>
            `;
            document.body.appendChild(modal);
        };

        App.addSOSToPrescription = function() {
            const chk1 = document.getElementById('chk-sos-1');
            const chk2 = document.getElementById('chk-sos-2');
            const custom = document.getElementById('txt-sos-custom');
            if (chk1?.checked) this.items.push({ med: chk1.value, poso: "", usage: "SOS", data: { type: 'SOS' } });
            if (chk2?.checked) this.items.push({ med: chk2.value, poso: "", usage: "CONDUTA", data: { type: 'SOS' } });
            if (custom?.value.trim()) this.items.push({ med: custom.value.trim().toUpperCase(), poso: "", usage: "SOS", data: { type: 'SOS' } });
            this.render();
            document.getElementById('sos-modal-pro').remove();
        };

        // 5. RENDER GERAL (Lê a configuração da data e Anti-Bug Fantasma)
        App.render = function() {
            
            if (typeof this._lastItemCount === 'undefined') this._lastItemCount = this.items.length;
            const currentCount = this.items.length;
            if (this._lastItemCount > 0 && currentCount === 0) {
                this.includeWardSheet = false;
                const wardBtn = document.getElementById('btn-ward-sheet') || document.querySelector('[onclick*="toggleWard"]');
                if (wardBtn) { wardBtn.classList.remove('active'); wardBtn.style.backgroundColor = ''; }
                const patName = document.getElementById('patient-name'); if (patName) patName.value = '';
                const prontInputs = document.querySelectorAll('.ward-prontuario-input'); prontInputs.forEach(inp => inp.value = '');
            }
            this._lastItemCount = currentCount; 

            this.items.forEach(it => {
                if (it.med && it.med.match(/\b(SOS|CONTENÇÃO|CONTENCAO|SE APM|MECÂNICA|MECANICA)\b/i)) {
                    if (!it.data) it.data = {};
                    it.data.type = 'SOS';
                }
            });

            const normals = this.items.filter(it => !(it.data && it.data.type === 'SOS'));
            const soses = this.items.filter(it => it.data && it.data.type === 'SOS');
            this.items = [...normals, ...soses]; 

            if (this.DOM.uiList) {
                this.DOM.uiList.innerHTML = this.items.map((it, i) => `<div class="item-row" draggable="true" data-index="${i}" oncontextmenu="App.showContextMenu(event, ${i})"><div class="item-row-content"><span>${it.med}</span><div class="row-actions"><button class="btn-icon" onclick="App.loadItemForEdit(${i})" title="Editar">✏️</button><button class="btn-icon btn-del" onclick="App.items.splice(${i},1);App.render()" title="Remover">×</button></div></div></div>`).join(''); 
            }

            const btnBatch = document.getElementById('btn-batch-lme'); 
            if(btnBatch) btnBatch.classList.toggle('hidden', !this.items.some(item => this.isHighCost(item.med))); 

            if(this.DOM.outputContainer) this.DOM.outputContainer.innerHTML = ""; 
            
            let groupedHighCost = {}; 
            if (this.lmeData && this.lmeData.active) { groupedHighCost = this.groupHighCostItems(this.lmeData.items); } 
            const hasLME = Object.keys(groupedHighCost).length > 0;
            
            let totalPagesPrescription = Math.ceil(normals.length / 5); 
            const hasExams = this.selectedExams && this.selectedExams.size > 0;
            let wardPagesCount = this.includeWardSheet ? Math.max(1, Math.ceil(this.items.length / 9)) : 0;
            
            if (totalPagesPrescription === 0 && !hasExams && !hasLME && wardPagesCount === 0) { totalPagesPrescription = 1; }
            const totalPages = totalPagesPrescription + (Object.keys(groupedHighCost).length * 2) + (hasExams ? 1 : 0) + wardPagesCount; 
            if (this.currentPage >= totalPages) this.currentPage = totalPages > 0 ? totalPages - 1 : 0; 
            
            const originalItems = this.items;
            this.items = normals; 
            
            // 👇 LÊ A CONFIGURAÇÃO DE DATA PADRÃO AQUI 👇
            const autoDate = localStorage.getItem('cerebrum_auto_date') !== 'false';

            for (let p = 0; p < totalPagesPrescription; p++) { 
                if (this.pageDateStates[p] === undefined) this.pageDateStates[p] = autoDate; 
                this.renderPrescriptionPage(p, totalPagesPrescription, this.pageDateStates[p]); 
            } 
            
            this.items = originalItems; 
            let indexOffset = totalPagesPrescription;
            
            if (hasLME) { 
                Object.keys(groupedHighCost).forEach(groupName => { 
                    if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate; 
                    this.renderSixMonthRecipe(groupedHighCost[groupName], indexOffset, this.pageDateStates[indexOffset]); 
                    if (this.pageDateStates[indexOffset + 1] === undefined) this.pageDateStates[indexOffset + 1] = autoDate; 
                    this.renderLMEPage(groupedHighCost[groupName], groupName, indexOffset + 1, this.pageDateStates[indexOffset + 1]); 
                    indexOffset += 2; 
                }); 
            } 
            
            if (hasExams) { 
                if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate;
                this.renderExamsPage(indexOffset); indexOffset += 1; 
            }

            if (wardPagesCount > 0) {
                for (let wp = 0; wp < wardPagesCount; wp++) {
                    if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate;
                    this.renderWardPage(indexOffset, wp);
                    indexOffset += 1;
                }
            }

            const sosBtn = document.getElementById('btn-sos-module');
            if (sosBtn) {
                const trueWardStart = totalPagesPrescription + (hasLME ? Object.keys(groupedHighCost).length * 2 : 0) + (hasExams ? 1 : 0);
                const isOnWardPage = this.includeWardSheet && (this.currentPage >= trueWardStart);
                sosBtn.style.display = isOnWardPage ? 'block' : 'none';
            }
            
            const navControls = document.getElementById('nav-controls'); if(navControls) navControls.classList.remove('hidden'); 
            const pageInd = document.getElementById('page-indicator'); if(pageInd) pageInd.innerText = `Página ${this.currentPage + 1} de ${totalPages || 1}`; 
            const prevPage = document.getElementById('prev-page'); if(prevPage) prevPage.disabled = this.currentPage === 0; 
            const nextPage = document.getElementById('next-page'); if(nextPage) nextPage.disabled = this.currentPage >= (totalPages || 1) - 1; 
            if (window.updatePageNavPills) window.updatePageNavPills();
            if(this.DOM.dateCheck) this.DOM.dateCheck.checked = !!this.pageDateStates[this.currentPage];

            setTimeout(() => {
                const syncInputs = document.querySelectorAll('.sync-pront-all');
                syncInputs.forEach(inp => {
                    inp.addEventListener('input', (e) => {
                        syncInputs.forEach(other => { 
                            if (other !== inp) {
                                other.value = e.target.value;
                                other.setAttribute('value', e.target.value);
                            }
                        });
                    });
                });
            }, 100);
        };

        // 6. RENDERIZAÇÃO DA FOLHA DE INTERNAMENTO
        App.renderWardPage = function(globalPageIndex, wardPageIndex = 0) {
            const isHidden = globalPageIndex !== this.currentPage ? 'hidden' : '';
            const patientName = document.getElementById('patient-name')?.value.toUpperCase() || '';
            const signature = (this.config && this.config.signature) ? `<img src="${this.config.signature}" style="position:absolute; bottom:6.5%; left:14%; max-width:250px; max-height:80px; object-fit:contain; z-index:5;">` : '';

            const today = new Date();
            const dd = String(today.getDate()).padStart(2, '0');
            const mm = String(today.getMonth() + 1).padStart(2, '0');
            const yyyy = today.getFullYear();

            const formatNum = (val) => { 
                let v = parseFloat(val) || 0;
                if (v === 0) return "00";
                if (v < 10 && Number.isInteger(v)) return "0" + v;
                if (v === 0.25) return "1/4"; if (v === 0.5) return "1/2"; if (v === 0.75) return "3/4";
                return v.toString().replace('.', ',');
            };

            let medRows = '';
            const startY = 41; 
            const stepY = 4.5; 

            const itemsSlice = this.items.slice(wardPageIndex * 9, (wardPageIndex * 9) + 9);

            itemsSlice.forEach((item, index) => {
                const y = startY + (index * stepY);
                let medName = item.med.toUpperCase().replace(/\s*\(\s*(COMP|GOTAS\/ML|AMP\/INJ|COMPRIMIDOS?|GOTAS|AMPOLAS?)\s*\)\s*$/i, '');
                
                const isSOS = (item.data && item.data.type === 'SOS');

                if (isSOS) {
                    let sosText = item.med;
                    sosText = sosText.replace("FENERGAM 25MG/ML, AMBOS", "FENERGAM 25MG/ML,<br>AMBOS");

                    medRows += `
                        <div class="ward-item-text" style="position: absolute; top: ${y}%; left: 6.8%; width: 85%; display: flex; align-items: center;">
                            <span style="font-size: 11.5px; font-weight: 800; color: #000; line-height: 1.3;">${sosText}</span>
                        </div>
                    `;
                } else {
                    const isInject = (item.data && item.data.type === 'INJECT') || medName.match(/\b(INJ|INJET[AÁ]VEL|AMPOLA|DECANOATO)\b/i);

                    if (isInject) {
                        const qty = parseFloat(item.data?.m) || 0;
                        const days = parseFloat(item.data?.t) || 0;
                        const ampLabel = qty > 1 ? "AMPOLAS" : "AMPOLA";
                        
                        let via = "INTRAMUSCULAR";
                        if (medName.match(/\bIV\b|\bEV\b|\bINTRAVENOSA\b/i)) via = "INTRAVENOSA";
                        else if (medName.match(/\bSC\b|\bSUBCUT[AÂ]NEA\b/i)) via = "SUBCUTÂNEA";

                        let posoInject = `USO: ${formatNum(qty)} ${ampLabel} POR VIA ${via} A CADA ${formatNum(days)} DIAS.`;

                        medRows += `
                            <div class="ward-item-text" style="position: absolute; top: ${y}%; left: 6.8%; width: 44%; display: flex; flex-direction: column; align-items: flex-start; justify-content: center;">
                                <span style="font-size: 12.5px; font-weight: 900; color: #000; line-height: 1.1;">${medName}</span>
                                <span style="font-size: 10px; font-weight: normal; color: #000; margin-top: 1px;">${posoInject}</span>
                            </div>
                        `;
                    } else {
                        let m = formatNum(item.data?.m); let t = formatNum(item.data?.t); let n = formatNum(item.data?.n);
                        let posoCompacta = `${m} &nbsp;&nbsp;-&nbsp;&nbsp; ${t} &nbsp;&nbsp;-&nbsp;&nbsp; ${n}`;

                        medRows += `
                            <div class="ward-item-text" style="position: absolute; top: ${y}%; left: 6.8%; width: 45%; display: grid; grid-template-columns: 240px auto; align-items: center; gap: 5px;">
                                <span style="font-size: 13.5px; font-weight: 900; color: #000; line-height: 1.1; display: block; word-break: break-word;">${medName}</span>
                                <span style="font-size: 15px; font-weight: 900; color: #000; letter-spacing: 1px; white-space: nowrap; text-align: right;">${posoCompacta}</span>
                            </div>
                        `;
                    }
                }
            });

            const posDia = "18.5%";  
            const posMes = "22.5%";  
            const posAno = "26.0%";  

            const fullHtml = `
                <div class="ward-print-wrapper ${isHidden}">
                    <div class="ward-landscape-page">
                        <img src="PRESCRIÇÃO MÉDICA ATUALIZADA_page-0001.jpg" class="ward-bg-img">
                        <div style="position:absolute; z-index:10; font-weight:900; font-size:22px; color:black; top:17.0%; left:10.5%; width:58%; text-transform:uppercase;">${patientName}</div>
                        <input type="text" class="ward-prontuario-input sync-pront-all" style="position:absolute; z-index:999 !important; top:15.5%; left:81%; width:15%; border:none; background:transparent; font-size:22px; font-weight:900; color:#000 !important; text-align:center; outline:none;" placeholder="---">
                        
                        ${medRows}
                        ${signature}
                        
                        <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posDia};">${dd}</div>
                        <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posMes};">${mm}</div>
                        <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posAno};">${yyyy}</div>
                    </div>
                </div>
            `;
            if (this.DOM.outputContainer) this.DOM.outputContainer.insertAdjacentHTML('beforeend', fullHtml);
        };

        // 7. VASSOURA DOS BOTÕES DE LIMPAR / FINALIZAR
        const allButtons = document.querySelectorAll('button, a');
        allButtons.forEach(btn => {
            const text = btn.textContent.toLowerCase();
            if (text.includes('limpar') || text.includes('nova presc') || text.includes('imprimir') || text.includes('finalizar')) {
                btn.addEventListener('click', () => {
                    setTimeout(() => {
                        if (App.items.length === 0) {
                            App.includeWardSheet = false;
                            App.pageDateStates = []; 
                            const wardBtn = document.getElementById('btn-ward-sheet') || document.querySelector('[onclick*="toggleWard"]');
                            if (wardBtn) { wardBtn.classList.remove('active'); wardBtn.style.backgroundColor = ''; }
                            App.render();
                        }
                    }, 500); 
                });
            }
        });

        if (App.items) App.render();
    }
}, 9500);
// =========================================================================
// 🌟 PATCH V63: PRÉ-VISUALIZAÇÃO LIVRE + BLOQUEIO DE INTERNAMENTO/IMPRESSÃO
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {

        App.pageDateStates = {};

        // =====================================================================
        // 🔒 1. BLOQUEIOS DE SEGURANÇA (A MÁGICA QUE VOCÊ PEDIU)
        // =====================================================================
        
        // A. Impede a criação da Folha de Prescrição (Internamento) vazia!
        App.generateAutoWardPrescription = function() {
            const pName = document.getElementById('patient-name') ? document.getElementById('patient-name').value.trim() : '';
            
            if (!pName) {
                if (this.showNotification) this.showNotification("⚠️ Preencha o Nome do Paciente primeiro.", "warning");
                return;
            }
            if (!this.items || this.items.length === 0) {
                if (this.showNotification) this.showNotification("⚠️ Adicione medicações antes de gerar a Folha de Prescrição.", "warning");
                return;
            }
            
            // Se tiver nome e remédio, ele libera a criação da folha!
            this.includeWardSheet = !this.includeWardSheet;
            if (this.includeWardSheet) {
                if (this.showNotification) this.showNotification("🏥 Folha de Internamento gerada com sucesso.", "success");
                setTimeout(() => {
                    const total = parseInt(document.getElementById('page-indicator')?.innerText.split(' de ')[1]) || 1;
                    this.currentPage = total - 1;
                    this.render();
                }, 50);
            } else {
                if (this.showNotification) this.showNotification("Folha de Internamento removida.", "info");
                this.currentPage = 0;
                this.render();
            }
        };

        // B. Impede a Impressão e Registro se a receita estiver vazia!
        if (!App.originalPrintCheckV63) {
            App.originalPrintCheckV63 = App.printAndSave;
            App.printAndSave = function() {
                const pName = document.getElementById('patient-name') ? document.getElementById('patient-name').value.trim() : '';
                const hasItems = this.items && this.items.length > 0;
                const hasExams = this.selectedExams && this.selectedExams.size > 0;
                const hasLME = this.lmeData && this.lmeData.active;
                const printBtn = document.getElementById('btn-print') || document.querySelector('button[onclick*="printAndSave"]');
                
                if (!pName) {
                    if (printBtn) {
                        printBtn.classList.remove('btn-shake');
                        void printBtn.offsetWidth;
                        printBtn.classList.add('btn-shake');
                        setTimeout(() => printBtn.classList.remove('btn-shake'), 600);
                    }
                    return this.showNotification("⚠️ Preencha o nome do paciente antes de imprimir.", "warning");
                }
                if (!hasItems && !hasExams && !hasLME) {
                    if (printBtn) {
                        printBtn.classList.remove('btn-shake');
                        void printBtn.offsetWidth;
                        printBtn.classList.add('btn-shake');
                        setTimeout(() => printBtn.classList.remove('btn-shake'), 600);
                    }
                    return this.showNotification("⚠️ A receita está vazia! Adicione medicações.", "error");
                }
                
                // Feedback visual de carregamento
                if (printBtn) {
                    printBtn.dataset.printing = 'true';
                    printBtn.classList.add('is-printing');
                    const titleEl = printBtn.querySelector('.btn-print-title');
                    if (titleEl) titleEl.textContent = 'GERANDO IMPRESSÃO...';
                }

                // Se a Central de Impressão (Print Hub) estiver ativada nas configurações:
                if (typeof this.isPrintHubEnabled === 'function' && this.isPrintHubEnabled()) {
                    if (printBtn) {
                        delete printBtn.dataset.printing;
                        printBtn.classList.remove('is-printing');
                        if (typeof App.updatePrintButton === 'function') {
                            App.updatePrintButton();
                        }
                    }
                    this.openPrintHub();
                    return;
                }

                // Se desativado nas configurações, imprime e salva direto!
                App.originalPrintCheckV63.call(this);

                setTimeout(() => {
                    if (printBtn) {
                        delete printBtn.dataset.printing;
                        printBtn.classList.remove('is-printing');
                        if (typeof App.updatePrintButton === 'function') {
                            App.updatePrintButton();
                        }
                    }
                }, 1200);
            };

            // Atalho universal Ctrl+P / Cmd+P
            if (!window.__prescriptCtrlPBound) {
                window.__prescriptCtrlPBound = true;
                window.addEventListener('keydown', (e) => {
                    if ((e.ctrlKey || e.metaKey) && (e.key === 'p' || e.key === 'P')) {
                        e.preventDefault();
                        e.stopPropagation();
                        if (typeof App !== 'undefined' && typeof App.printAndSave === 'function') {
                            App.printAndSave();
                        }
                    }
                }, true);
            }
        }

        // =====================================================================
        // ⚙️ 2. CONFIGURAÇÕES DA DATA E MENU
        // =====================================================================
        if (!App.originalOpenSettingsForDate) {
            App.originalOpenSettingsForDate = App.openSettings;
        }

        App.openSettings = function(tab) {
            if (window.SettingsPro && typeof window.SettingsPro.open === 'function') return window.SettingsPro.open(tab);
            if (typeof openSettingsPro === 'function') return openSettingsPro(tab);
            App.originalOpenSettingsForDate.call(this);
            setTimeout(() => {
                const userTab = document.getElementById('e-tab-user');
                if (userTab) {
                    const section = userTab.querySelector('.ent-section');
                    if (section && !document.getElementById('ent-cfg-autodate')) {
                        const autoDateState = this.config && this.config.autoDateDefault !== false;
                        const toggleHtml = `
                            <div class="ent-toggle-wrapper" style="animation: entFadeIn 0.3s ease-out forwards;">
                                <div class="ent-toggle-info">
                                    <span class="ent-label">Data Ativa por Padrão</span>
                                    <span class="ent-hint">Ativa automaticamente a data em todas as novas prescrições, receitas e folhas.</span>
                                </div>
                                <label class="ent-switch">
                                    <input type="checkbox" id="ent-cfg-autodate" ${autoDateState ? 'checked' : ''}>
                                    <span class="ent-slider"></span>
                                </label>
                            </div>
                        `;
                        section.insertAdjacentHTML('afterbegin', toggleHtml);
                    }
                }
            }, 50);
        };

        App.saveEnterpriseSettings = function() {
            if (!this.currentProfile) return;
            if (!this.currentProfile.config) this.currentProfile.config = {};

            const theme = document.getElementById('ent-cfg-theme') ? document.getElementById('ent-cfg-theme').value : 'theme-modern';
            const hideFooter = document.getElementById('ent-cfg-hidefooter') ? document.getElementById('ent-cfg-hidefooter').checked : false;
            const autoClear = document.getElementById('ent-cfg-autoclear') ? document.getElementById('ent-cfg-autoclear').checked : true;
            const onlyFirstDate = document.getElementById('ent-cfg-firstdate') ? document.getElementById('ent-cfg-firstdate').checked : true;
            const spaceToggle = document.getElementById('ent-cfg-spacetoggle') ? document.getElementById('ent-cfg-spacetoggle').checked : true;
            
            const autoDateEl = document.getElementById('ent-cfg-autodate');
            const autoDateDefault = autoDateEl ? autoDateEl.checked : true;
            
            const title = document.getElementById('ent-cfg-title') ? document.getElementById('ent-cfg-title').value.trim() : '';
            const sub = document.getElementById('ent-cfg-sub') ? document.getElementById('ent-cfg-sub').value.trim() : '';
            const cnes = document.getElementById('ent-cfg-cnes') ? document.getElementById('ent-cfg-cnes').value.trim() : '';
            const tel = document.getElementById('ent-cfg-tel') ? document.getElementById('ent-cfg-tel').value.trim() : '';
            const addr = document.getElementById('ent-cfg-addr') ? document.getElementById('ent-cfg-addr').value.trim() : '';
            
            const sDrawer = document.getElementById('ent-cfg-drawer') ? document.getElementById('ent-cfg-drawer').value.toUpperCase() || 'I' : 'I';
            const sClear = document.getElementById('ent-cfg-clear') ? document.getElementById('ent-cfg-clear').value.toUpperCase() || 'X' : 'X';
            const sDate = document.getElementById('ent-cfg-date') ? document.getElementById('ent-cfg-date').value.toUpperCase() || 'D' : 'D';
            const sFraction = document.getElementById('ent-cfg-fraction') ? document.getElementById('ent-cfg-fraction').value.toUpperCase() || 'F' : 'F';
            const sLote = document.getElementById('ent-cfg-lote') ? document.getElementById('ent-cfg-lote').value.toUpperCase() || 'L' : 'L';

            const favTextEl = document.getElementById('ent-cfg-favs');
            const favoritesArr = favTextEl ? favTextEl.value.split('\n').map(m => m.trim().toUpperCase()).filter(m => m !== '') : [];

            const allKeys = [sDrawer, sClear, sDate, sFraction, sLote];
            if (allKeys.length !== new Set(allKeys).size) return this.showNotification("Aviso: Existem teclas de atalho repetidas. Altere para evitar conflitos.", "warning");

            this.config.theme = theme;
            this.config.hideFooterPrint = hideFooter;
            this.config.autoClearAfterPrint = autoClear;
            this.config.onlyFirstDate = onlyFirstDate;
            this.config.spaceToggle = spaceToggle;
            this.config.autoDateDefault = autoDateDefault; 
            
            this.config.title = title;
            this.config.sub = sub;
            this.config.cnes = cnes;
            this.config.tel = tel;
            this.config.addr = addr;

            this.config.shortcutDrawer = sDrawer;
            this.config.shortcutClear = sClear;
            this.config.shortcutDate = sDate;
            this.config.shortcutFraction = sFraction;
            this.config.shortcutLote = sLote;
            this.config.favorites = favoritesArr;
            
            if (this.tempCustomMeds) this.config.customMeds = this.tempCustomMeds;
            if (this.invalidateMedsCache) this.invalidateMedsCache();

            if (this.tempLmeBg) { this.config.lmeBg = this.tempLmeBg; delete this.tempLmeBg; }

            this.currentProfile.config = this.config;
            this.profiles[this.currentProfileIndex] = this.currentProfile;
            localStorage.setItem('caps_pro_profiles', JSON.stringify(this.profiles));
            
            document.body.classList.remove('theme-modern', 'theme-blue', 'theme-dark', 'theme-light');
            document.body.classList.add(theme);
            document.body.classList.add('logged-in');
            document.body.classList.remove('hide-floating-menu');
            
            if(this.syncToCloud) this.syncToCloud();
            this.closeSettings();
            this.render();
            this.showNotification("Configurações salvas e aplicadas com sucesso.", "success");
        };

        // =====================================================================
        // 🖼️ 3. RENDERIZAÇÃO DA PÁGINA
        // =====================================================================
        App.render = function() {
            
            const autoDate = this.config ? this.config.autoDateDefault !== false : true;

            // Limpa a memória se o paciente for apagado
            if (typeof this._lastItemCount === 'undefined') this._lastItemCount = this.items.length;
            const currentCount = this.items.length;
            if (this._lastItemCount > 0 && currentCount === 0) {
                this.includeWardSheet = false;
                this.pageDateStates = {}; 
                const wardBtn = document.getElementById('btn-ward-sheet') || document.querySelector('[onclick*="toggleWard"]');
                if (wardBtn) { wardBtn.classList.remove('active'); wardBtn.style.backgroundColor = ''; }
                const patName = document.getElementById('patient-name'); if (patName) patName.value = '';
                const prontInputs = document.querySelectorAll('.ward-prontuario-input'); prontInputs.forEach(inp => inp.value = '');
            }
            this._lastItemCount = currentCount; 

            // Organiza SOS
            this.items.forEach(it => {
                if (it.med && it.med.match(/\b(SOS|CONTENÇÃO|CONTENCAO|SE APM|MECÂNICA|MECANICA)\b/i)) {
                    if (!it.data) it.data = {};
                    it.data.type = 'SOS';
                }
            });

            const normals = this.items.filter(it => !(it.data && it.data.type === 'SOS'));
            const soses = this.items.filter(it => it.data && it.data.type === 'SOS');
            this.items = [...normals, ...soses]; 

            // Atualiza a lista lateral com as medicações
            if (this.DOM.uiList) {
                this.DOM.uiList.innerHTML = this.items.map((it, i) => `<div class="item-row" draggable="true" data-index="${i}" oncontextmenu="App.showContextMenu(event, ${i})"><div class="item-row-content"><span>${it.med}</span><div class="row-actions"><button class="btn-icon" onclick="App.loadItemForEdit(${i})" title="Editar">✏️</button><button class="btn-icon btn-del" onclick="App.items.splice(${i},1);App.render()" title="Remover">×</button></div></div></div>`).join(''); 
            }

            const btnBatch = document.getElementById('btn-batch-lme'); 
            if(btnBatch) btnBatch.classList.toggle('hidden', !this.items.some(item => this.isHighCost(item.med))); 

            if(this.DOM.outputContainer) this.DOM.outputContainer.innerHTML = ""; 
            
            let groupedHighCost = {}; 
            if (this.lmeData && this.lmeData.active) { groupedHighCost = this.groupHighCostItems(this.lmeData.items); } 
            const hasLME = Object.keys(groupedHighCost).length > 0;
            
            let totalPagesPrescription = Math.ceil(normals.length / 5); 
            const hasExams = this.selectedExams && this.selectedExams.size > 0;
            let wardPagesCount = this.includeWardSheet ? Math.max(1, Math.ceil(this.items.length / 9)) : 0;
            
            // Garante que, mesmo vazia, a página 1 (Receita Comum) nasça na tela!
            if (totalPagesPrescription === 0 && !hasExams && !hasLME && wardPagesCount === 0) { totalPagesPrescription = 1; }
            
            const totalPages = totalPagesPrescription + (Object.keys(groupedHighCost).length * 2) + (hasExams ? 1 : 0) + wardPagesCount; 
            if (this.currentPage >= totalPages) this.currentPage = totalPages > 0 ? totalPages - 1 : 0; 
            
            const originalItems = this.items;
            this.items = normals; 
            
            for (let p = 0; p < totalPagesPrescription; p++) { 
                if (this.pageDateStates[p] === undefined) this.pageDateStates[p] = autoDate; 
                this.renderPrescriptionPage(p, totalPagesPrescription, this.pageDateStates[p]); 
            } 
            
            this.items = originalItems; 
            let indexOffset = totalPagesPrescription;
            
            if (hasLME) { 
                Object.keys(groupedHighCost).forEach(groupName => { 
                    if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate; 
                    this.renderSixMonthRecipe(groupedHighCost[groupName], indexOffset, this.pageDateStates[indexOffset]); 
                    if (this.pageDateStates[indexOffset + 1] === undefined) this.pageDateStates[indexOffset + 1] = autoDate; 
                    this.renderLMEPage(groupedHighCost[groupName], groupName, indexOffset + 1, this.pageDateStates[indexOffset + 1]); 
                    indexOffset += 2; 
                }); 
            } 
            
            if (hasExams) { 
                if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate;
                this.renderExamsPage(indexOffset); indexOffset += 1; 
            }

            if (wardPagesCount > 0) {
                for (let wp = 0; wp < wardPagesCount; wp++) {
                    if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate;
                    this.renderWardPage(indexOffset, wp);
                    indexOffset += 1;
                }
            }

            const sosBtn = document.getElementById('btn-sos-module');
            if (sosBtn) {
                const trueWardStart = totalPagesPrescription + (hasLME ? Object.keys(groupedHighCost).length * 2 : 0) + (hasExams ? 1 : 0);
                const isOnWardPage = this.includeWardSheet && (this.currentPage >= trueWardStart);
                sosBtn.style.display = isOnWardPage ? 'block' : 'none';
            }
            
            const navControls = document.getElementById('nav-controls'); if(navControls) navControls.classList.remove('hidden'); 
            const pageInd = document.getElementById('page-indicator'); if(pageInd) pageInd.innerText = `Página ${this.currentPage + 1} de ${totalPages || 1}`; 
            const prevPage = document.getElementById('prev-page'); if(prevPage) prevPage.disabled = this.currentPage === 0; 
            const nextPage = document.getElementById('next-page'); if(nextPage) nextPage.disabled = this.currentPage >= (totalPages || 1) - 1; 
            if (window.updatePageNavPills) window.updatePageNavPills();
            if(this.DOM.dateCheck) this.DOM.dateCheck.checked = !!this.pageDateStates[this.currentPage];

            setTimeout(() => {
                const syncInputs = document.querySelectorAll('.sync-pront-all');
                syncInputs.forEach(inp => {
                    inp.addEventListener('input', (e) => {
                        syncInputs.forEach(other => { 
                            if (other !== inp) {
                                other.value = e.target.value;
                                other.setAttribute('value', e.target.value);
                            }
                        });
                    });
                });
            }, 100);
        };

        // Força a atualização inicial
        if (App.items) App.render();
    }
}, 10000);
