                                <input type="text" id="pro-input-crm" value="${p.crm || ''}" style="background:#0b1120; border:1px solid #334155; color:#fff; padding:12px; border-radius:8px; font-size:14px; outline:none; width:100%; box-sizing:border-box; transition: 0.2s;" onfocus="this.style.borderColor='#38bdf8'" onblur="this.style.borderColor='#334155'">
                            </div>
