// 🌌 PATCH V88: DESIGN DARK NEON / CYBER-GLASS (LISTAS E DROPDOWN)
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {
        
        // 1. INJETA O CSS DARK NEON (E DESTRAVA A CAIXA MÃE)
        const styleId = 'neo-lists-v88-css';
        let style = document.getElementById(styleId);
        if(style) style.remove();
        
        style = document.createElement('style');
        style.id = styleId;
        style.innerHTML = `
            /* 🚨 DESTRAVA A CAIXA MÃE PARA A LISTA PODER CAIR 🚨 */
            #apple-search-master-wrap {
                overflow: visible !important; 
            }

            /* =======================================================
               A LISTA DE PESQUISA (ESTILO DARK NEON)
               ======================================================= */
            #med-dropdown {
                position: absolute !important;
                top: calc(100% + 12px) !important;
                left: 0 !important;
                width: 100% !important;
                background: #020617 !important; /* Fundo ultra escuro */
                border: 1px solid #1e293b !important;
                border-radius: 12px !important;
                box-shadow: 0 20px 40px rgba(0,0,0,0.9), 0 0 20px rgba(56, 189, 248, 0.05) !important;
                padding: 10px 0 !important;
                max-height: 380px !important;
                overflow-y: auto !important;
                z-index: 9999999 !important; 
                box-sizing: border-box !important;
                animation: neoDrop 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards !important;
                transform-origin: top center;
            }

            @keyframes neoDrop {
                from { opacity: 0; transform: translateY(-15px) scale(0.98); }
                to { opacity: 1; transform: translateY(0) scale(1); }
            }

            #med-dropdown::-webkit-scrollbar { width: 6px; }
            #med-dropdown::-webkit-scrollbar-thumb { background: rgba(56, 189, 248, 0.2); border-radius: 10px; }
            #med-dropdown::-webkit-scrollbar-thumb:hover { background: rgba(56, 189, 248, 0.5); }

            .neo-search-cat {
                font-family: 'Inter', sans-serif !important;
                font-size: 10px !important;
                font-weight: 900 !important;
                color: #7dd3fc !important; /* Azul claro */
                padding: 0 0 6px 0 !important;
                margin: 12px 16px 6px 16px !important;
                text-transform: uppercase !important;
                letter-spacing: 2px !important;
                border-bottom: 1px dashed #1e293b !important;
                display: flex !important; align-items: center !important; gap: 8px !important;
            }

            .neo-search-item {
                padding: 10px 16px !important;
                margin: 2px 8px !important;
                border-radius: 8px !important;
                border-left: 3px solid transparent !important;
                display: flex !important;
                align-items: center !important;
                gap: 12px !important;
                color: #cbd5e1 !important;
                cursor: pointer !important;
                font-size: 14px !important;
                font-weight: 600 !important;
                transition: all 0.2s ease !important;
            }

            /* 🌟 EFEITO NEON: Fio de luz à esquerda e gradiente 🌟 */
            .neo-search-item:hover {
                background: linear-gradient(90deg, rgba(56, 189, 248, 0.15) 0%, transparent 100%) !important;
                border-left-color: #38bdf8 !important;
                color: #ffffff !important;
                transform: translateX(4px) !important;
            }

            .neo-item-icon {
                display: flex !important; align-items: center !important; justify-content: center !important;
                width: 24px !important; height: 24px !important;
                font-size: 14px !important;
                opacity: 0.7 !important;
                transition: 0.2s !important;
            }
            .neo-search-item:hover .neo-item-icon {
                opacity: 1 !important;
                transform: scale(1.1) !important;
                filter: drop-shadow(0 0 5px rgba(255,255,255,0.5)) !important;
            }

            .neo-item-text {
                flex: 1 !important;
                white-space: nowrap !important;
                overflow: hidden !important;
                text-overflow: ellipsis !important;
            }

            .neo-item-action {
                opacity: 0 !important;
                font-size: 14px !important;
                color: #38bdf8 !important;
                font-weight: bold !important;
                transition: 0.2s !important;
            }
            .neo-search-item:hover .neo-item-action { opacity: 1 !important; transform: translateX(-4px) !important;}

            .neo-highlight {
                font-weight: 900 !important;
                color: #fff !important;
                text-shadow: 0 0 8px rgba(56, 189, 248, 0.6) !important;
            }

            /* =======================================================
               A LISTA DE REMÉDIOS ADICIONADOS (FLOATING CARDS)
               ======================================================= */
            #ui-items-list {
                background: transparent !important;
                border: none !important;
                box-shadow: none !important;
                padding: 0 !important;
                margin-top: 15px !important;
            }

            /* Transforma cada linha num cartão independente flutuante */
            #ui-items-list .item-row {
                background: rgba(15, 23, 42, 0.6) !important;
                border: 1px solid rgba(56, 189, 248, 0.15) !important;
                margin: 0 0 10px 0 !important; /* Espaço entre os cartões */
                padding: 14px 18px !important;
                border-radius: 12px !important;
                box-shadow: 0 4px 10px rgba(0,0,0,0.2) !important;
                transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) !important;
            }

            #ui-items-list .item-row:hover {
                background: rgba(15, 23, 42, 0.95) !important;
                border-color: #38bdf8 !important;
                box-shadow: 0 8px 20px rgba(0,0,0,0.4), 0 0 15px rgba(56, 189, 248, 0.15) !important;
                transform: translateY(-2px) !important;
            }

            #ui-items-list .item-row-content span { 
                font-weight: 700 !important; 
                font-size: 14px !important; 
                color: #f8fafc !important; 
                letter-spacing: 0.3px !important;
            }

            #ui-items-list .btn-icon {
                background: rgba(255, 255, 255, 0.03) !important; 
                border-radius: 8px !important;
                width: 32px !important; height: 32px !important; display: flex !important;
                align-items: center !important; justify-content: center !important; transition: 0.2s !important;
                border: 1px solid transparent !important;
            }
            #ui-items-list .btn-icon:hover { background: rgba(56, 189, 248, 0.15) !important; border-color: rgba(56, 189, 248, 0.3) !important; transform: scale(1.1) !important; }
            #ui-items-list .btn-icon.btn-del:hover { background: rgba(239, 68, 68, 0.15) !important; color: #ef4444 !important; border-color: rgba(239, 68, 68, 0.3) !important;}
        `;
        document.head.appendChild(style);

        // 2. GARANTE QUE A LISTA EXISTE NO LUGAR CERTO DO HTML
        const wrap = document.getElementById('apple-search-master-wrap');
        const input = document.getElementById('med-search');
        
        if (wrap && input) {
            let dropdown = document.getElementById('med-dropdown');
            
            if (!dropdown) {
                dropdown = document.createElement('div');
                dropdown.id = 'med-dropdown';
                dropdown.style.display = 'none';
                wrap.appendChild(dropdown);
            } else if (dropdown.parentElement !== wrap) {
                wrap.appendChild(dropdown);
            }

            if (App.DOM) App.DOM.medDropdown = dropdown;

            // 3. REESCREVE A FUNÇÃO DE FILTRO (GERA O HTML DARK NEON)
            App.filterMeds = function(query) {
                const drop = document.getElementById('med-dropdown');
                const searchInput = document.getElementById('med-search');
                if (!drop) return;
                
                const q = (query || "").trim().toUpperCase(); 
                drop.innerHTML = ''; 
                let hasResults = false; 
                let allMedsDict = this.getAllMeds(); 
                let medsToSearch = allMedsDict;
                
                if (this.isFavFilterActive) { 
                    medsToSearch = {}; 
                    for (const [cat, medList] of Object.entries(allMedsDict)) { 
                        const favsInCat = medList.filter(m => this.config.favorites.includes(m)); 
                        if (favsInCat.length > 0) medsToSearch[cat] = favsInCat; 
                    } 
                }
                
                const frag = document.createDocumentFragment();
                
                for (const [category, meds] of Object.entries(medsToSearch)) {
                    const matches = meds.filter(m => m.includes(q));
                    if (matches.length > 0) {
                        hasResults = true; 
                        
                        let icon = "💊";
                        if(category.includes("LÍQUIDO") || category.includes("GOTAS") || category.includes("SOLUÇÃO")) icon = "💧";
                        if(category.includes("INJETÁVEIS") || category.includes("DEPOT")) icon = "💉";
                        
                        let cleanCat = category.replace(/[💊💧💉]/g, '').trim();

                        const catHeader = document.createElement('div'); 
                        catHeader.className = 'neo-search-cat'; 
                        catHeader.innerHTML = `<span>${cleanCat}</span>`; 
                        frag.appendChild(catHeader);
                        
                        matches.forEach(med => { 
                            const item = document.createElement('div'); 
                            item.className = 'neo-search-item'; 
                            
                            let medHtml = med;
                            if (q) {
                                const regex = new RegExp(`(${q.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&')})`, 'gi');
                                medHtml = med.replace(regex, `<span class="neo-highlight">$1</span>`);
                            }
                            
                            item.innerHTML = `
                                <div class="neo-item-icon">${icon}</div>
                                <div class="neo-item-text">${medHtml}</div>
                                <div class="neo-item-action">ADICIONAR</div>
                            `;
                            
                            item.onclick = (e) => { 
                                e.stopPropagation();
                                if(searchInput) searchInput.value = med; 
                                drop.style.display = 'none'; 
                                if (document.getElementById('lme-dose-m')) document.getElementById('lme-dose-m').value = '0';
                                if (document.getElementById('lme-dose-t')) document.getElementById('lme-dose-t').value = '0';
                                if (document.getElementById('lme-dose-n')) document.getElementById('lme-dose-n').value = '0';
                                this.checkCategory(med); 
                            }; 
                            
                            frag.appendChild(item); 
                        });
                    }
                }
                
                drop.appendChild(frag); 
                drop.style.display = hasResults ? 'block' : 'none';
            };

            // 4. FORÇA O EVENTO DE CLIQUE A FUNCIONAR
            const triggerSearch = (e) => {
                e.stopPropagation();
                if (App.filterMeds) App.filterMeds(input.value || '');
            };
            
            input.removeEventListener('focus', triggerSearch);
            input.removeEventListener('click', triggerSearch);
            
            input.addEventListener('focus', triggerSearch);
            input.addEventListener('click', triggerSearch);
            
            input.oninput = (e) => {
                if (App.debouncedFilterMeds) {
                    App.debouncedFilterMeds(e.target.value);
                } else {
                    App.filterMeds(e.target.value);
                }
            };
        }
    }
}, 3000);
// =========================================================================
// 👻 PATCH V89: FIX DO EFEITO FANTASMA NO MODO LOTE (LIMPEZA PÓS-SALVAR)
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {
        
        // Intercepta a função de salvar (Adicionar Medicamento)
        if (!App.originalHandleSaveV89) {
            App.originalHandleSaveV89 = App.handleSave;
            
            App.handleSave = async function() {
                // 1. Deixa o sistema executar a validação e salvar a medicação normalmente
                await App.originalHandleSaveV89.call(this);
                
                // 2. Se estivermos no Modo Lote, limpamos a lente holográfica!
                if (this.DOM.modeFast && this.DOM.modeFast.checked && this.DOM.fastInput) {
                    
                    // Dispara um evento de "digitação falsa" para obrigar o IntelliSense a atualizar e perceber que a caixa está vazia
                    const event = new Event('input', { bubbles: true });
                    this.DOM.fastInput.dispatchEvent(event);
                    
                    // Trava de segurança absoluta: Se a caixa original estiver vazia, pulveriza o texto do fundo colorido
                    const highlights = document.getElementById('fast-input-highlights');
                    if (highlights && this.DOM.fastInput.value.trim() === "") {
                        highlights.innerHTML = "";
                        App.loteHasErrors = false; // Reseta o estado de erro
                    }
                }
            };
        }
        
    }
}, 3500); // 3.5s garante que ele se sobrepõe a todos os outros interceptadores do botão Salvar
// =========================================================================
// 🍏 PATCH V90: DESIGN PREMIUM DO CAMPO EMBALAGEM (CUSTOM SELECT APPLE)
// =========================================================================
function initAppleCustomSelect() {
    if (typeof document === 'undefined') return;
    
    // 1. INJETA O CSS DO NOVO SELECT E PORTAL
    const styleId = 'apple-custom-select-css';
    let style = document.getElementById(styleId);
    if (!style) {
        style = document.createElement('style');
        style.id = styleId;
        document.head.appendChild(style);
    }
    style.innerHTML = `
        .apple-select-wrapper {
            position: relative;
            width: 100%;
            user-select: none;
            margin-top: 5px;
        }

        /* A Caixa Principal Fechada */
        .apple-select-trigger {
            display: flex;
            align-items: center;
            justify-content: space-between;
            background: rgba(15, 23, 42, 0.6) !important;
            backdrop-filter: blur(15px);
            border: 1px solid rgba(255, 255, 255, 0.1);
            padding: 0 16px;
            height: 48px;
            border-radius: 12px;
            color: #f8fafc;
            font-family: 'Inter', sans-serif;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
            box-shadow: inset 0 2px 4px rgba(0,0,0,0.3);
        }

        /* Efeitos de Interação na Caixa */
        .apple-select-trigger:hover {
            background: rgba(30, 41, 59, 0.8) !important;
            border-color: rgba(56, 189, 248, 0.4);
        }
        
        .apple-select-wrapper.open .apple-select-trigger {
            border-color: #38bdf8;
            background: #0f172a !important;
            box-shadow: 0 0 0 3px rgba(56,189,248,0.15), inset 0 2px 4px rgba(0,0,0,0.4);
        }

        .apple-select-icon {
            color: #94a3b8;
            display: flex;
            align-items: center;
            transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .apple-select-wrapper.open .apple-select-icon {
            transform: rotate(180deg);
            color: #38bdf8;
        }

        /* A Lista Suspensa Portal (Anexada ao BODY, imune a overflow:hidden de qualquer card) */
        .apple-select-options {
            position: fixed !important;
            background: rgba(15, 23, 42, 0.96) !important;
            backdrop-filter: blur(35px) saturate(200%) !important;
            -webkit-backdrop-filter: blur(35px) saturate(200%) !important;
            border: 1px solid rgba(255, 255, 255, 0.18) !important;
            border-radius: 14px !important;
            box-shadow: 0 25px 50px rgba(0,0,0,0.85), inset 0 0 0 1px rgba(255,255,255,0.08) !important;
            max-height: 290px;
            overflow-y: auto !important;
            overscroll-behavior: contain !important;
            padding: 6px !important;
            opacity: 0 !important;
            pointer-events: none !important;
            transform: translateY(-8px) scale(0.98) !important;
            transition: opacity 0.22s cubic-bezier(0.16, 1, 0.3, 1), transform 0.22s cubic-bezier(0.16, 1, 0.3, 1) !important;
            z-index: 2147483647 !important;
            box-sizing: border-box !important;
            display: block !important;
        }

        .apple-select-options::-webkit-scrollbar {
            width: 6px;
        }
        .apple-select-options::-webkit-scrollbar-track {
            background: transparent;
        }
        .apple-select-options::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.2);
            border-radius: 10px;
        }
        .apple-select-options::-webkit-scrollbar-thumb:hover {
            background: rgba(56, 189, 248, 0.6);
        }

        .apple-select-options.open {
            opacity: 1 !important;
            pointer-events: auto !important;
            transform: translateY(0) scale(1) !important;
        }

        /* Cada Item da Lista */
        .apple-select-option {
            padding: 10px 14px;
            color: #cbd5e1;
            cursor: pointer;
            transition: all 0.15s ease;
            font-size: 13.5px;
            font-weight: 500;
            border-radius: 8px;
            display: flex;
            align-items: center;
            gap: 10px;
            margin-bottom: 2px;
            user-select: none;
        }

        .apple-select-option:last-child { margin-bottom: 0; }

        /* Hover no Item (Azul Apple Sólido) */
        .apple-select-option:hover {
            background: #007aff !important;
            color: #ffffff !important;
            transform: translateX(4px);
        }

        /* Item que está selecionado atualmente */
        .apple-select-option.selected {
            background: rgba(56, 189, 248, 0.15) !important;
            color: #38bdf8 !important;
            font-weight: 800 !important;
        }
        .apple-select-option.selected:hover {
            background: #007aff !important;
            color: #ffffff !important;
        }

        /* Blindagem para garantir que o card de dados não corte popups */
        #card-dados .card-content,
        .pro-section:not(.collapsed) .card-content {
            overflow: visible !important;
        }
    `;

    // 2. MAGIA DE SUBSTITUIÇÃO DO DOM
    const originalSelect = document.getElementById('pack-type');
    
    if (originalSelect && !originalSelect.dataset.customized) {
        originalSelect.dataset.customized = 'true';
        originalSelect.style.display = 'none';
        
        const getPackIcon = (text) => {
            const t = (text || '').toLowerCase();
            if (t.includes("contínuo") || t.includes("continuo")) return "♾️";
            if (t.includes("frasco") && t.includes("ampola")) return "🧪";
            if (t.includes("ampola")) return "💉";
            if (t.includes("frasco") || t.includes("gota")) return "🧴";
            if (t.includes("comprimido") || t.includes("cápsula") || t.includes("capsula")) return "💊";
            if (t.includes("bisnaga") || t.includes("tubo")) return "🧴";
            if (t.includes("sachê") || t.includes("sache") || t.includes("envelope")) return "✉️";
            if (t.includes("cartela") || t.includes("blister")) return "📑";
            if (t.includes("spray") || t.includes("aerossol") || t.includes("inalador")) return "💨";
            if (t.includes("caneta") || t.includes("refil")) return "🖊️";
            if (t.includes("seringa")) return "💉";
            if (t.includes("adesivo") || t.includes("patch")) return "🩹";
            if (t.includes("pote")) return "🍯";
            if (t.includes("unidade")) return "🔢";
            return "📦";
        };

        const wrapper = document.createElement('div');
        wrapper.className = 'apple-select-wrapper';
        
        const trigger = document.createElement('div');
        trigger.className = 'apple-select-trigger';
        
        const textNode = document.createElement('span');
        textNode.style.display = 'flex';
        textNode.style.alignItems = 'center';
        textNode.style.gap = '8px';
        
        const updateTrigger = () => {
            const curOpt = originalSelect.options[originalSelect.selectedIndex] || originalSelect.options[0];
            if (curOpt) {
                const iconEmoji = getPackIcon(curOpt.text);
                textNode.innerHTML = `<span>${iconEmoji}</span> <span>${curOpt.text}</span>`;
            }
        };
        updateTrigger();

        const icon = document.createElement('div');
        icon.className = 'apple-select-icon';
        icon.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>`;
        
        trigger.appendChild(textNode);
        trigger.appendChild(icon);
        
        // 🌟 O PORTAL DA LISTA (VIVE NO BODY, IMUNE AO OVERFLOW DE QUALQUER CARD) 🌟
        let optionsDiv = document.getElementById('portal-apple-select-options');
        if (optionsDiv) optionsDiv.remove();
        optionsDiv = document.createElement('div');
        optionsDiv.id = 'portal-apple-select-options';
        optionsDiv.className = 'apple-select-options';
        document.body.appendChild(optionsDiv);
        
        const positionOptions = () => {
            const rect = trigger.getBoundingClientRect();
            const dropdownMaxHeight = 290;
            const spaceBelow = window.innerHeight - rect.bottom;
            const spaceAbove = rect.top;
            
            const finalWidth = Math.max(rect.width, 240);
            let finalLeft = rect.left;
            if (finalLeft + finalWidth > window.innerWidth - 12) {
                finalLeft = Math.max(12, window.innerWidth - finalWidth - 12);
            }
            optionsDiv.style.setProperty('left', `${finalLeft}px`, 'important');
            optionsDiv.style.setProperty('width', `${finalWidth}px`, 'important');
            
            if (spaceBelow < 220 && spaceAbove > spaceBelow) {
                // Abre para cima
                const actualH = Math.min(dropdownMaxHeight, Math.max(120, spaceAbove - 16));
                optionsDiv.style.setProperty('max-height', `${actualH}px`, 'important');
                optionsDiv.style.setProperty('top', 'auto', 'important');
                optionsDiv.style.setProperty('bottom', `${window.innerHeight - rect.top + 6}px`, 'important');
                optionsDiv.style.transformOrigin = 'bottom center';
            } else {
                // Abre para baixo
                const actualH = Math.min(dropdownMaxHeight, Math.max(120, spaceBelow - 16));
                optionsDiv.style.setProperty('max-height', `${actualH}px`, 'important');
                optionsDiv.style.setProperty('bottom', 'auto', 'important');
                optionsDiv.style.setProperty('top', `${rect.bottom + 6}px`, 'important');
                optionsDiv.style.transformOrigin = 'top center';
            }
        };
        
        const openDropdown = () => {
            positionOptions();
            optionsDiv.classList.add('open');
            wrapper.classList.add('open');
        };
        
        const closeDropdown = () => {
            optionsDiv.classList.remove('open');
            wrapper.classList.remove('open');
        };
        
        Array.from(originalSelect.options).forEach((opt, index) => {
            const optDiv = document.createElement('div');
            optDiv.className = 'apple-select-option';
            if (opt.selected) optDiv.classList.add('selected');
            
            const itemIcon = getPackIcon(opt.text);
            optDiv.innerHTML = `<span>${itemIcon}</span> <span>${opt.text}</span>`;
            
            optDiv.addEventListener('click', (e) => {
                e.stopPropagation();
                originalSelect.value = opt.value;
                updateTrigger();
                
                Array.from(optionsDiv.children).forEach(c => c.classList.remove('selected'));
                optDiv.classList.add('selected');
                closeDropdown();
                
                originalSelect.dispatchEvent(new Event('change', { bubbles: true }));
            });
            
            optionsDiv.appendChild(optDiv);
        });
        
        trigger.addEventListener('click', (e) => {
            e.stopPropagation();
            if (optionsDiv.classList.contains('open')) {
                closeDropdown();
            } else {
                openDropdown();
            }
        });
        
        document.addEventListener('pointerdown', (e) => {
            if (!wrapper.contains(e.target) && !optionsDiv.contains(e.target)) {
                closeDropdown();
            }
        });
        
        window.addEventListener('scroll', () => {
            if (optionsDiv.classList.contains('open')) {
                positionOptions();
            }
        }, { passive: true, capture: true });
        
        window.addEventListener('resize', () => {
            if (optionsDiv.classList.contains('open')) {
                positionOptions();
            }
        });
        
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && optionsDiv.classList.contains('open')) {
                closeDropdown();
            }
        });
        
        wrapper.appendChild(trigger);
        originalSelect.parentNode.insertBefore(wrapper, originalSelect.nextSibling);
        
        originalSelect.addEventListener('change', () => {
            updateTrigger();
            Array.from(optionsDiv.children).forEach(c => c.classList.remove('selected'));
            if (optionsDiv.children[originalSelect.selectedIndex]) {
                optionsDiv.children[originalSelect.selectedIndex].classList.add('selected');
            }
        });
    }
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => setTimeout(initAppleCustomSelect, 100));
    window.addEventListener('load', () => setTimeout(initAppleCustomSelect, 250));
} else {
    setTimeout(initAppleCustomSelect, 100);
    setTimeout(initAppleCustomSelect, 300);
    setTimeout(initAppleCustomSelect, 800);
} // 3 segundos para garantir que todo o HTML do formulário já foi construído
// =========================================================================
// 📝 PATCH V93: FIX DEFINITIVO DA CAIXA DE OBSERVAÇÕES (ANTI-OUTLINE QUADRADO)
// =========================================================================
setTimeout(() => {
    if (typeof document !== 'undefined') {
        
        // 1. INJETAR O CSS BLINDADO COM MÁXIMA ESPECIFICIDADE
        const styleId = 'premium-obs-box-css';
        let style = document.getElementById(styleId);
        if (style) style.remove();

        style = document.createElement('style');
        style.id = styleId;
        style.innerHTML = `
            /* 🚨 MATA O OUTLINE NATIVO EM QUALQUER ESTADO 🚨 */
            textarea#obs-input,
            .custom-input#obs-input {
                appearance: none !important;
                -webkit-appearance: none !important;
                width: 100% !important;
                min-height: 110px !important;
                background: rgba(15, 23, 42, 0.5) !important;
                backdrop-filter: blur(12px) !important;
                -webkit-backdrop-filter: blur(12px) !important;
                border: 1px solid rgba(255, 255, 255, 0.08) !important;
                border-radius: 12px !important;
                padding: 16px !important;
                color: #f8fafc !important;
                font-family: 'Inter', -apple-system, sans-serif !important;
                font-size: 14px !important;
                line-height: 1.6 !important;
                resize: vertical !important;
                box-shadow: inset 0 2px 6px rgba(0,0,0,0.4) !important;
                transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) !important;
                box-sizing: border-box !important;
                
                /* ASSASSINATO DO OUTLINE QUADRADO */
                outline: none !important; 
                outline-offset: 0 !important;
            }

            textarea#obs-input::placeholder,
            .custom-input#obs-input::placeholder {
                color: #64748b !important;
                font-weight: 500 !important;
                letter-spacing: 0.3px !important;
            }

            /* 🌟 EFEITO DE FOCO USANDO APENAS BORDER E BOX-SHADOW (RESPEITA AS CURVAS) 🌟 */
            textarea#obs-input:focus, 
            textarea#obs-input:focus-visible, 
            textarea#obs-input:active,
            .custom-input#obs-input:focus,
            .custom-input#obs-input:focus-visible {
                background: rgba(15, 23, 42, 0.9) !important;
                border: 1px solid #38bdf8 !important; /* Usa borda real em vez de outline */
                outline: none !important; /* Garante que o navegador não se intrometa */
                box-shadow: 0 8px 25px rgba(0,0,0,0.4), inset 0 2px 4px rgba(0,0,0,0.2), 0 0 0 3px rgba(56, 189, 248, 0.2) !important;
                transform: translateY(-2px) !important;
            }

            textarea#obs-input:hover:not(:focus),
            .custom-input#obs-input:hover:not(:focus) {
                background: rgba(30, 41, 59, 0.7) !important;
                border: 1px solid rgba(255, 255, 255, 0.15) !important;
            }

            /* Scrollbar Customizada */
            textarea#obs-input::-webkit-scrollbar { width: 6px !important; }
            textarea#obs-input::-webkit-scrollbar-track { background: transparent !important; border-radius: 8px !important; margin: 4px !important; }
            textarea#obs-input::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.15) !important; border-radius: 8px !important; }
            textarea#obs-input::-webkit-scrollbar-thumb:hover { background: rgba(56, 189, 248, 0.5) !important; }
        `;
        document.head.appendChild(style);

        // 2. GARANTE QUE NADA VAI SOBRESCREVER A NOSSA CAIXA
        const obsInput = document.getElementById('obs-input');
        if (obsInput) {
            // Remove lixo em linha que possa estar a forçar a borda errada
            obsInput.style.outline = 'none';
        }
    }
}, 1500);
// =========================================================================
// 🌌 PATCH V96: NOTIFICAÇÕES PROFISSIONAIS (SUPERIOR DIREITO + ANIMAÇÕES)
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {
        
        // 1. INJETA O CSS DAS NOTIFICAÇÕES PREMIUM
        const styleId = 'cyber-toasts-css';
        let style = document.getElementById(styleId);
        if (style) style.remove();

        style = document.createElement('style');
        style.id = styleId;
        style.innerHTML = `
            /* Oculta os contentores de testes anteriores */
            #toast-container, #apple-toast-container { display: none !important; opacity: 0 !important; visibility: hidden !important; }

            /* O NOVO CONTENTOR (CANTO SUPERIOR DIREITO) */
            #cyber-toast-container {
                position: fixed !important;
                top: 25px !important;
                right: 25px !important; /* Fixado à direita */
                display: flex !important;
                flex-direction: column !important;
                gap: 15px !important;
                z-index: 99999999 !important;
                pointer-events: none !important;
            }

            /* O CARTÃO DA NOTIFICAÇÃO (VIDRO NEON) */
            .cyber-toast {
                position: relative !important;
                background: rgba(15, 23, 42, 0.85) !important;
                backdrop-filter: blur(20px) !important;
                -webkit-backdrop-filter: blur(20px) !important;
                border: 1px solid rgba(255, 255, 255, 0.1) !important;
                border-radius: 12px !important;
                width: 340px !important;
                display: flex !important;
                align-items: center !important;
                padding: 16px !important;
                box-shadow: 0 15px 35px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.05) !important;
                pointer-events: auto !important; 
                overflow: hidden !important; /* Para a barra de progresso não vazar */
                
                /* Animação de Entrada Elástica (Vindo da Direita) */
                animation: cyberEntryRight 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards !important;
                transform-origin: right center;
                will-change: transform, opacity;
            }

            /* ANIMAÇÃO DE ENTRADA (Vindo da direita com rebote) */
            @keyframes cyberEntryRight {
                0% { opacity: 0; transform: translateX(120%) scale(0.9) skewX(-10deg); filter: blur(5px); }
                100% { opacity: 1; transform: translateX(0) scale(1) skewX(0); filter: blur(0); }
            }

            /* ANIMAÇÃO DE SAÍDA (Desliza de volta para a direita e some) */
            .cyber-toast.hiding {
                animation: cyberExitRight 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards !important;
            }
            @keyframes cyberExitRight {
                to { opacity: 0; transform: translateX(100%) scale(0.95); filter: blur(5px); }
            }

            /* BORDA LATERAL LUMINOSA */
            .cyber-toast::before {
                content: '' !important;
                position: absolute !important;
                top: 0 !important; left: 0 !important;
                width: 4px !important; height: 100% !important;
                background: var(--toast-color, #38bdf8) !important;
                box-shadow: 0 0 15px var(--toast-color, #38bdf8) !important;
            }

            /* ÁREA DO ÍCONE */
            .cyber-toast-icon-box {
                display: flex !important;
                align-items: center !important;
                justify-content: center !important;
                width: 40px !important;
                height: 40px !important;
                border-radius: 10px !important;
                background: var(--toast-bg-color, rgba(56, 189, 248, 0.15)) !important;
                color: var(--toast-color, #38bdf8) !important;
                font-size: 20px !important;
                margin-right: 15px !important;
                flex-shrink: 0 !important;
                border: 1px solid var(--toast-border-color, rgba(56, 189, 248, 0.3)) !important;
            }

            /* ÁREA DE TEXTO */
            .cyber-toast-content {
                flex: 1 !important;
                display: flex !important;
                flex-direction: column !important;
                justify-content: center !important;
            }
            .cyber-toast-title {
                color: #f8fafc !important;
                font-family: 'Inter', sans-serif !important;
                font-size: 14px !important;
                font-weight: 800 !important;
                margin: 0 0 4px 0 !important;
                letter-spacing: 0.5px !important;
                text-transform: uppercase !important;
            }
            .cyber-toast-msg {
                color: #cbd5e1 !important;
                font-family: 'Inter', sans-serif !important;
                font-size: 13px !important;
                font-weight: 500 !important;
                line-height: 1.4 !important;
            }

            /* BARRA DE PROGRESSO (Tempo restante) */
            .cyber-toast-progress {
                position: absolute !important;
                bottom: 0 !important;
                left: 0 !important;
                height: 3px !important;
                background: var(--toast-color, #38bdf8) !important;
                box-shadow: 0 -2px 10px var(--toast-color, #38bdf8) !important;
                animation: toastProgress 4s linear forwards !important; /* Duração do Toast */
            }
            @keyframes toastProgress {
                0% { width: 100%; }
                100% { width: 0%; }
            }

            /* VARIÁVEIS DE CORES DINÂMICAS */
            .cyber-toast.success { --toast-color: #10b981; --toast-bg-color: rgba(16, 185, 129, 0.15); --toast-border-color: rgba(16, 185, 129, 0.3); }
            .cyber-toast.error { --toast-color: #ef4444; --toast-bg-color: rgba(239, 68, 68, 0.15); --toast-border-color: rgba(239, 68, 68, 0.3); }
            .cyber-toast.warning { --toast-color: #facc15; --toast-bg-color: rgba(250, 204, 21, 0.15); --toast-border-color: rgba(250, 204, 21, 0.3); }
            .cyber-toast.info { --toast-color: #38bdf8; --toast-bg-color: rgba(56, 189, 248, 0.15); --toast-border-color: rgba(56, 189, 248, 0.3); }
        `;
        document.head.appendChild(style);

        // 2. O MOTOR QUE GERA AS NOTIFICAÇÕES
        App.showNotification = function(msg, type = 'info') {
            // Garante que o contentor existe
            let container = document.getElementById('cyber-toast-container');
            if (!container) {
                container = document.createElement('div');
                container.id = 'cyber-toast-container';
                document.body.appendChild(container);
            }

            // Define o Ícone e o Título consoante a gravidade
            let iconHtml = '';
            let titleText = 'Sistema';

            if (type === 'success') {
                iconHtml = `✓`; 
                titleText = 'Sucesso';
            } else if (type === 'error') {
                iconHtml = `✕`; 
                titleText = 'Erro Crítico';
            } else if (type === 'warning') {
                iconHtml = `!`; 
                titleText = 'Atenção';
            } else {
                iconHtml = `i`; 
                titleText = 'Informação';
            }

            // Monta o Cartão HTML
            const toast = document.createElement('div');
            toast.className = `cyber-toast ${type}`;
            toast.innerHTML = `
                <div class="cyber-toast-icon-box">${iconHtml}</div>
                <div class="cyber-toast-content">
                    <div class="cyber-toast-title">${titleText}</div>
                    <div class="cyber-toast-msg">${msg}</div>
                </div>
                <div class="cyber-toast-progress"></div>
            `;

            // Permite ao utilizador fechar a notificação se clicar nela
            toast.onclick = () => {
                toast.classList.add('hiding');
                setTimeout(() => { if (toast.parentNode) toast.remove(); }, 400);
            };

            // Adiciona no contentor (a nova vai empurrar a velha para baixo)
            container.prepend(toast);

            // Temporizador absoluto (4 segundos)
            setTimeout(() => {
                toast.classList.add('hiding');
                toast.addEventListener('animationend', () => toast.remove());
                setTimeout(() => { if (toast.parentNode) toast.remove(); }, 500); // Failsafe
            }, 4000); 
        };
    }
}, 1000);
// =========================================================================
// 🍏 PATCH V102: THE APEX SPOTLIGHT SEARCH (PORTAL ABSOLUTO + CORREÇÃO)
