    // 1. LIMPEZA DE ESTILOS ANTIGOS DA BARRA DE PESQUISA (Previne conflitos)
    const lixoCSS = ['search-bar-v81-css', 'search-bar-v82-css', 'search-bar-v83-css', 'search-dropdown-v84-css', 'search-dropdown-v85-css', 'apple-lists-v86-css', 'apple-lists-v87-css', 'neo-lists-v88-css', 'portal-dropdown-css'];
