// ✍️ PATCH V108: SISTEMA DE ASSINATURA DIGITAL (UPLOAD E IMPRESSÃO)
// =========================================================================
setTimeout(() => {
    if (typeof App === 'undefined') return;

    // 1. INJETAR CSS DA ASSINATURA NA IMPRESSÃO
    const styleId = 'signature-print-css';
    if (!document.getElementById(styleId)) {
        const style = document.createElement('style');
        style.id = styleId;
        // Localiza esta parte no final do teu script.js (dentro do style.innerHTML do PATCH V108):
style.innerHTML = `
    .print-signature-img {
        position: absolute;
        bottom: 25px; 
        left: 50%;
        transform: translateX(-50%);
        
        /* ALTERA ESTES VALORES PARA DIMINUIR */
        max-height: 50px; /* Reduzido de 80px para 50px */
        max-width: 180px;  /* Reduzido de 250px para 180px */
        
        object-fit: contain;
        mix-blend-mode: multiply;
        z-index: 5;
        pointer-events: none;
    }
    .footer-mini { position: relative; }
`;
        document.head.appendChild(style);
    }

    // 2. FUNÇÕES DE PROCESSAMENTO E COMPRESSÃO DA IMAGEM
    App.handleSignatureUpload = function(event) {
        const file = event.target.files[0];
        if (!file) return;

        // Cria um link temporário para ler a imagem sem travar a memória
        const imgUrl = URL.createObjectURL(file);
        const img = new Image();
        
        img.onload = () => {
            // Usa o Canvas do HTML5 para comprimir e esmagar a imagem
            const canvas = document.createElement('canvas');
            const MAX_SIZE = 400; // Resolução ideal para não pesar o Firebase
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_SIZE) { height = Math.round(height * (MAX_SIZE / width)); width = MAX_SIZE; }
            } else {
                if (height > MAX_SIZE) { width = Math.round(width * (MAX_SIZE / height)); height = MAX_SIZE; }
            }

            canvas.width = width; canvas.height = height;
            const ctx = canvas.getContext('2d');
            
            // Força fundo branco caso seja um PNG com transparência defeituosa
            ctx.fillStyle = '#ffffff'; 
            ctx.fillRect(0, 0, canvas.width, canvas.height); 
            ctx.drawImage(img, 0, 0, width, height);

            // Converte para JPEG leve (Economiza até 80% do espaço)
            const compressedBase64 = canvas.toDataURL('image/jpeg', 0.7); 

            if (!this.config) this.config = {};
            this.config.signature = compressedBase64;
            
            this.checkSignatureImage();
            if (this.showNotification) this.showNotification("Assinatura anexada com sucesso! Lembre-se de Salvar as Configurações.", "success");
            
            URL.revokeObjectURL(imgUrl); // Limpa o lixo da RAM
        };
        
        img.onerror = () => {
            if (this.showNotification) this.showNotification("Erro ao processar imagem.", "error");
        };
        
        img.src = imgUrl;
    };

    App.removeSignature = function() {
        if (this.config) this.config.signature = null;
        this.checkSignatureImage();
        if (this.showNotification) this.showNotification("Assinatura removida. Salve as configurações.", "info");
    };

    App.checkSignatureImage = function() {
        const img = document.getElementById('preview-signature');
        const btnRemove = document.getElementById('btn-remove-sig');
        if (!img) return;

        if (this.config && this.config.signature) {
            img.src = this.config.signature;
            img.style.display = 'inline-block';
            if (btnRemove) btnRemove.style.display = 'inline-flex';
        } else {
            img.src = '';
            img.style.display = 'none';
            if (btnRemove) btnRemove.style.display = 'none';
        }
    };

    // 3. INTERCEPTAR O PAINEL DE CONFIGURAÇÕES PARA INJETAR A ÁREA DE UPLOAD
    if (!App.originalOpenSettingsForSignature) {
        App.originalOpenSettingsForSignature = App.openSettings;
        
        App.openSettings = function(tab) {
            if (window.SettingsPro && typeof window.SettingsPro.open === 'function') return window.SettingsPro.open(tab);
            if (typeof openSettingsPro === 'function') return openSettingsPro(tab);
            // Abre o painel normalmente
            App.originalOpenSettingsForSignature.call(this);
            
            // Injeta o campo de assinatura na aba "Receituário" (#e-tab-doc)
            setTimeout(() => {
                const docTab = document.getElementById('e-tab-doc');
                if (docTab) {
                    const sections = docTab.querySelectorAll('.ent-section');
                    const lastSection = sections[sections.length - 1]; // Pega o último bloco de formulário
                    
                    if (lastSection && !document.getElementById('signature-upload-wrapper')) {
                        const sigHtml = `
                            <div class="ent-form-col" id="signature-upload-wrapper" style="margin-top: 25px; border-top: 1px dashed #334155; padding-top: 25px;">
                                <label class="ent-label" style="color: #38bdf8; font-size: 16px;">✍️ Assinatura Digital e Carimbo</label>
                                <span class="ent-hint" style="margin-bottom: 12px; display: block;">Faça upload de uma foto da sua assinatura/carimbo. Ela será impressa automaticamente sobre a linha no final da receita. O sistema deixará o fundo branco transparente.</span>
                                
                                <div style="background: rgba(0,0,0,0.2); border: 1px dashed rgba(56, 189, 248, 0.3); border-radius: 12px; padding: 20px; text-align: center;">
                                    <img id="preview-signature" src="" style="max-width: 100%; max-height: 100px; object-fit: contain; margin-bottom: 15px; display: none; mix-blend-mode: screen; background: white; padding: 10px; border-radius: 8px; margin-left: auto; margin-right: auto;">
                                    
                                    <div style="display: flex; justify-content: center; gap: 15px;">
                                        <input type="file" id="signature-upload-input" accept="image/png, image/jpeg" style="display: none;" onchange="App.handleSignatureUpload(event)">
                                        <button type="button" class="ent-btn ent-btn-ghost" style="border-color: #38bdf8; color: #38bdf8;" onclick="document.getElementById('signature-upload-input').click()">
                                            📸 Anexar Imagem
                                        </button>
                                        <button type="button" id="btn-remove-sig" class="ent-btn ent-btn-danger" style="display: none;" onclick="App.removeSignature()">
                                            🗑️ Remover
                                        </button>
                                    </div>
                                </div>
                            </div>
                        `;
                        lastSection.insertAdjacentHTML('beforeend', sigHtml);
                        
                        // Exibe a assinatura se o médico já a tiver guardada na memória
                        this.checkSignatureImage(); 
                    }
                }
            }, 100); // 100ms garante que a tela das configurações já foi desenhada pelo navegador
        };
    }

}, 4000); // Roda 4s após a carga do sistema, garantindo segurança na injeção.
