// 💎 PATCH V109: IMPLEMENTAÇÃO DA ASSINATURA DIGITAL NO LME
// =========================================================================
setTimeout(() => {
    if (typeof App !== 'undefined') {

        // 1. INJETA O ESTILO DE POSICIONAMENTO DA ASSINATURA NO LME
        const styleId = 'lme-signature-css';
        if (!document.getElementById(styleId)) {
            const style = document.createElement('style');
            style.id = styleId;
            style.innerHTML = `
                /* Posicionamento da Assinatura dentro da folha do LME */
                .lme-signature-overlay {
                    position: absolute !important;
                    /* Coordenadas para o campo 'Assinatura e carimbo do médico' do LME */
                    bottom: 22% !important; 
                    right: 13% !important;
                    max-height: 50px !important;
                    max-width: 180px !important;
                    object-fit: contain !important;
                    mix-blend-mode: multiply !important; /* Remove fundo branco da foto */
                    z-index: 100 !important;
                    pointer-events: none !important;
                }
                
                /* Garante que o container do LME aceite posições absolutas */
                .lme-bg-page { position: relative !important; }
            `;
            document.head.appendChild(style);
        }

        // 2. ATUALIZA A FUNÇÃO RENDERLMEPAGE PARA INCLUIR A IMAGEM
        const originalRenderLME = App.renderLMEPage;
        
        App.renderLMEPage = function(items, groupName, pageIndex, showDate) {
            // Primeiro, pegamos o HTML base que a função original geraria
            // (Ou reescrevemos para garantir a injeção da assinatura)
            
            const isHidden = pageIndex !== this.currentPage ? 'hidden' : ''; 
            const bgSrc = this.config.lmeBg || ""; 
            const anamnese = this.lmeData.anamnese.replace(/\(Medicações prescritas\)/g, groupName); 
            const dateRaw = new Date(); 
            const dateStr = dateRaw.toLocaleDateString('pt-BR'); 
            const visibilityClass = showDate ? '' : 'invisible'; 
            
            let fields = items.slice(0, 3).map((item, i) => { 
                let qtyMonthly = 0; 
                if (item.data.type === 'INJECT') { 
                    qtyMonthly = Math.ceil((30 / (item.data.t||30)) * (item.data.m||1)); 
                } else { 
                    qtyMonthly = Math.ceil(((parseFloat(item.data.m)||0) + (parseFloat(item.data.t)||0) + (parseFloat(item.data.n)||0)) * 30); 
                } 
                let cols = ""; 
                for(let c=1; c<=6; c++) { 
                    cols += `<div class="lme-overlay-field pos-qty${c}-${i+1}">${qtyMonthly}</div>`; 
                } 
                return `<div class="lme-overlay-field pos-med-${i+1}">${item.med}</div>` + cols; 
            }).join(''); 
            
            const safeName = (this.lmeData && this.lmeData.patientName) ? this.lmeData.patientName : ((this.DOM.patientInput ? this.DOM.patientInput.value : "").toUpperCase());
            
            // Mágica da Assinatura:
            const signatureImg = this.config.signature ? `<img src="${this.config.signature}" class="lme-signature-overlay">` : '';

            const pageHtml = `
                <div class="lme-bg-page ${isHidden}">
                    ${bgSrc ? `<img src="${bgSrc}" class="lme-img-layer">` : ''}
                    <div class="lme-overlay-field pos-cnes">${this.config.cnes}</div>
                    <div class="lme-overlay-field pos-estab">${this.config.title}</div>
                    <div class="lme-overlay-field pos-paciente">${safeName}</div>
                    ${fields}
                    <div class="lme-overlay-field pos-cid">${this.lmeData.cidCode}</div>
                    <div class="lme-overlay-field pos-diag">${this.lmeData.cidName}</div>
                    <div class="lme-overlay-field pos-anamnese">${anamnese}</div>
                    <div class="lme-overlay-field pos-check-trat-nao">X</div>
                    <div class="lme-overlay-field pos-check-cap-nao">X</div>
                    <div class="lme-overlay-field pos-medico">${this.config.docname}</div>
                    <div class="lme-overlay-field pos-cns-med">${this.config.doccns}</div>
                    <div class="lme-overlay-field pos-data ${visibilityClass}">${dateStr}</div>
                    <div class="lme-overlay-field pos-tel">${this.lmeData.tel}</div>
                    ${signatureImg} 
                </div>`; 
                
            if(this.DOM.outputContainer) this.DOM.outputContainer.insertAdjacentHTML('beforeend', pageHtml); 
        };

        // Redesenha para aplicar se houver um LME ativo na tela
        if (App.lmeData && App.lmeData.active) App.render();
    }
}, 4500);
