// 🧲 PATCH V2900: ANCORAGEM MAGNÉTICA DO CADEADO (RESOLUÇÕES PERFEITAS)
// =========================================================================
setTimeout(function() {
    if (typeof document === 'undefined') return;

    // 1. INJETA O CSS CORRETIVO (Para remover as posições absolutas antigas)
    const styleId = 'cadeado-magnetic-css';
    if (!document.getElementById(styleId)) {
        const style = document.createElement('style');
        style.id = styleId;
        style.innerHTML = `
            /* 1. Reseta a física do botão para que o Javascript possa movê-lo livremente */
            #cadeado-coroa-btn, #final-lock-btn, #smart-lock-btn {
                transform: none !important;
                margin: 0 !important;
                /* Removemos o delay de movimento para ele colar na folha em tempo real */
                transition: color 0.3s, background 0.3s, filter 0.3s, transform 0.2s !important; 
            }
            
            /* 2. Novos Hovers de Animação sem usar o translateX antigo */
            #cadeado-coroa-btn.locked:hover, #final-lock-btn.locked:hover {
                transform: scale(1.15) !important;
            }
            #cadeado-coroa-btn.unlocked:hover, #final-lock-btn.unlocked:hover {
                transform: scale(1.15) !important;
                animation: none !important;
            }
            #cadeado-coroa-btn:active, #final-lock-btn:active {
                transform: scale(0.9) !important;
            }
            
            /* 3. Nova Pulsação perfeitamente alinhada */
            @keyframes coroaPulseAligned { 
                0% { filter: drop-shadow(0 0 2px rgba(245,158,11,0.2)); transform: scale(1); } 
                100% { filter: drop-shadow(0 0 8px rgba(245,158,11,0.6)); transform: scale(1.05); } 
            }
            #cadeado-coroa-btn.unlocked, #final-lock-btn.unlocked {
                animation: coroaPulseAligned 2.5s infinite alternate !important;
            }
        `;
        document.head.appendChild(style);
    }

    // 2. RADAR MAGNÉTICO (60 FRAMES POR SEGUNDO)
    // Esta função persegue a folha branca na tela e cola o botão nela
    function trackPaper() {
        const lockBtn = document.getElementById('cadeado-coroa-btn') || document.getElementById('final-lock-btn') || document.getElementById('smart-lock-btn');
        
        // Caça a folha que está atualmente visível (Receita, LME ou Internamento)
        const activePage = document.querySelector('.a4-page:not(.hidden), .lme-bg-page:not(.hidden), .ward-print-wrapper:not(.hidden) .ward-landscape-page');
        
        if (lockBtn && activePage) {
            // Se o cadeado ainda não estiver dentro da página atual, move ele para lá
            if (lockBtn.parentElement !== activePage) {
                activePage.appendChild(lockBtn);
            }
            
            // O cadeado agora faz parte da página e sofrerá as mesmas alterações de zoom!
            lockBtn.style.setProperty('position', 'absolute', 'important');
            lockBtn.style.setProperty('top', '25px', 'important');
            lockBtn.style.setProperty('right', '35px', 'important');
            lockBtn.style.setProperty('left', 'auto', 'important');
            lockBtn.style.setProperty('z-index', '999999', 'important');
            lockBtn.style.transform = '';
        }
        
        // Loop infinito super leve sincronizado com a placa de vídeo
        requestAnimationFrame(trackPaper);
    }

    // Liga o Radar
    requestAnimationFrame(trackPaper);

}, 2500); // Entra aos 2.5s para garantir que todos os remendos antigos já carregaram
// =========================================================================
// ⚔️ PATCH V3000: HIGHLANDER (O EXTERMINADOR DE CLONES DO CADEADO)
// =========================================================================
setInterval(function() {
    if (typeof document === 'undefined') return;

    // 1. Caça todos os IDs de cadeados que criámos na nossa jornada
    var possibleLocks = document.querySelectorAll('#cadeado-coroa-btn, #final-lock-btn, #smart-lock-btn, #neo-lock-btn, #editor-lock-btn, #omega-lock-btn, #imortal-lock-btn, #titan-lock-btn, #cadeado-supremo-btn');

    // 2. Se o sistema detetar que há mais do que 1 cadeado vivo na tela...
    if (possibleLocks.length > 1) {
        // O primeiro (index 0) sobrevive, todos os outros são vaporizados
        for (var i = 1; i < possibleLocks.length; i++) {
            possibleLocks[i].remove();
        }
    }
    
    // 3. Aproveita para limpar também possíveis clones da barrinha de edição (Negrito/Itálico)
    var toolbars = document.querySelectorAll('#cerebrum-floating-toolbar');
    if (toolbars.length > 1) {
        for (var j = 1; j < toolbars.length; j++) {
            toolbars[j].remove();
        }
    }
    
    // 4. Limpeza extra de CSS que possa estar a prender o cadeado sobrevivente
    if (possibleLocks.length > 0) {
        var survivor = possibleLocks[0];
        survivor.style.margin = '0';
        survivor.style.transform = 'none';
    }

}, 400); // Roda a cada 400 milissegundos silenciosamente
