// 🛡️ PATCH VMAX 2.6: MOTOR DE TITÂNIO + DATA MAIS ALTA E AFASTADA DO CARIMBO
// =========================================================================
(function() {
    if (typeof App === 'undefined') return;

    // 1. INJETA CSS BLINDADO PARA LIMPAR QUALQUER "SUJEIRA" DE FUNDO E GARANTIR A IMPRESSÃO
    const styleId = 'cerebrum-titanium-css';
    if (!document.getElementById(styleId)) {
        const style = document.createElement('style');
        style.id = styleId;
        style.innerHTML = `
            /* Destrói fundos do botão na área de impressão */
            .print-wrapper, .action-wrapper, .bottom-actions, .finalizar-atendimento { background: transparent !important; border: none !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important;}
            .print-tip-text { display: none !important; } 
            
            /* CSS Perfeito da Folha de Internamento */
            .ward-print-wrapper { display: flex; justify-content: center; width: 100%; padding-bottom: 30px; }
            .ward-landscape-page { position: relative; width: 1122px; height: 793px; background: white; box-shadow: 0 15px 40px rgba(0,0,0,0.5); font-family: Arial, sans-serif; overflow: hidden; flex-shrink: 0; margin: 0 auto; transform-origin: top center; transform: scale(0.65); margin-bottom: -20%; }
            @media (max-width: 1600px) { .ward-landscape-page { transform: scale(0.55); margin-bottom: -30%; } }
            @media (max-width: 1300px) { .ward-landscape-page { transform: scale(0.45); margin-bottom: -40%; } }
            
            .ward-bg-img { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 1; pointer-events: none; object-fit: fill !important; }
            .ward-item-text { position: absolute; z-index: 2; color: black; line-height: 1.2; transform: translateY(-50%); white-space: normal !important;}
            .ward-print-wrapper.hidden, .ward-landscape-page.hidden { display: none !important; }
            .ward-copia-print { display: none !important; }

            /* Ajustes finos de Margem na Receita Comum */
            .content-mini { padding-top: 0px !important; margin-top: 0px !important; }
            .patient-block { margin-bottom: 6px !important; }
            .r-symbol { display: inline-block !important; margin-bottom: 0px !important; padding-bottom: 0px !important; }

            /* MÁGICA DE IMPRESSÃO */
            @media print {
                @page { size: 210mm 297mm; margin: 0mm !important; }
                #prontuario-drawer, #top-profile-module, #floating-actions-container, .ward-ui-controls, #nav-controls, .floating-menu-container { display: none !important; }
                
                .a4-page, .lme-bg-page { page-break-after: always !important; break-after: page !important; }
                
                .ward-print-wrapper { display: block !important; width: 210mm !important; height: 297mm !important; position: relative !important; page-break-after: always !important; overflow: hidden !important; background: white !important; margin: 0 !important; padding: 0 !important;}
                .ward-landscape-page { display: block !important; width: 297mm !important; height: 210mm !important; position: absolute !important; top: 297mm !important; left: 0 !important; transform-origin: 0 0 !important; transform: rotate(-90deg) !important; margin: 0 !important; padding: 0 !important; box-shadow: none !important; }
                .ward-prontuario-input { border: none !important; background: transparent !important; color: black !important;}
            }
        `;
        document.head.appendChild(style);
    }

    // Filtro de Abreviações e Marcas Comerciais (com controle por configuração)
    const ultimateExpandMed = function(name) { 
        if (!name) return ""; 
        let n = name.trim().toUpperCase(); 
        const allowTradenames = localStorage.getItem('cerebrum_lote_tradename_convert') !== 'false';
        
        // Abreviações médicas essenciais (sempre expandidas para segurança clínica)
        const abbrevDict = [ 
            { rx: /\b(H\.?\s*DEC(ANOATO)?)\b/g, full: "HALDOL DECANOATO" }, 
            { rx: /\bCBZ\b/g, full: "CARBAMAZEPINA" }, 
            { rx: /\bCZP\b/g, full: "CLONAZEPAM" }, 
            { rx: /\bDZP\b/g, full: "DIAZEPAM" }, 
            { rx: /\bRIS[SP]\b/g, full: "RISPERIDONA" }, 
            { rx: /\bESC ODT\b/g, full: "ESCITALOPRAM ODT" }, 
            { rx: /\bESC\b/g, full: "ESCITALOPRAM" }, 
            { rx: /\bDUAL\b/g, full: "DULOXETINA" }, 
            { rx: /\bCL[OÔ]\b/g, full: "CLOMIPRAMINA" }, 
            { rx: /\bAMI?TRIL\b/g, full: "AMITRIPTILINA" },
            { rx: /(?<!CARBONATO DE )\bL[IÍ]TIO\b/g, full: "CARBONATO DE LÍTIO" }
        ];
        for (let d of abbrevDict) { n = n.replace(d.rx, d.full); } 
        
        // Conversão automática de marcas comerciais para DCB (ativa conforme configuração)
        if (allowTradenames) {
            const brandDict = [
                { rx: /\bRIVOTRIL\b/g, full: "CLONAZEPAM" }, 
                { rx: /\bGARDENAL\b/g, full: "FENOBARBITAL" }, 
                { rx: /\bHALDOL\b/g, full: "HALOPERIDOL" }, 
                { rx: /\bFENERGAN\b/g, full: "PROMETAZINA" }, 
                { rx: /\bDEPAK[EO]T?E?\b/g, full: "VALPROATO DE SÓDIO" }, 
                { rx: /\bTEGRETOL\b/g, full: "CARBAMAZEPINA" }, 
                { rx: /\bAMPLICTIL\b/g, full: "CLORPROMAZINA" }, 
                { rx: /\bNEULEPTIL\b/g, full: "PERICIAZINA" }, 
                { rx: /\bPROZAC\b/g, full: "FLUOXETINA" }, 
                { rx: /\bDAFORIN\b/g, full: "FLUOXETINA" }, 
                { rx: /\bSEROQUEL\b/g, full: "QUETIAPINA" }, 
                { rx: /\bZYPREXA\b/g, full: "OLANZAPINA" }, 
                { rx: /\bLEPONEX\b/g, full: "CLOZAPINA" }, 
                { rx: /\bARISTAB\b/g, full: "ARIPIPRAZOL" }, 
                { rx: /\bPATZ\b/g, full: "ZOLPIDEM" }, 
                { rx: /\bSTILNOX\b/g, full: "ZOLPIDEM" },
                { rx: /\bLEXAPRO\b/g, full: "ESCITALOPRAM" },
                { rx: /\bFRONTAL\b/g, full: "ALPRAZOLAM" },
                { rx: /\bVALIUM\b/g, full: "DIAZEPAM" },
                { rx: /\bLEXOTAN\b/g, full: "BROMAZEPAM" },
                { rx: /\bLORAX\b/g, full: "LORAZEPAM" },
                { rx: /\bROHYPNOL\b/g, full: "FLUNITRAZEPAM" },
                { rx: /\bDORMONID\b/g, full: "MIDAZOLAM" },
                { rx: /\bNEOZINE\b/g, full: "LEVOMEPROMAZINA" },
                { rx: /\bRISPERDAL\b/g, full: "RISPERIDONA" },
                { rx: /\bZOLOFT\b/g, full: "SERTRALINA" },
                { rx: /\bCYMBALTA\b/g, full: "DULOXETINA" },
                { rx: /\bANAFRANIL\b/g, full: "CLOMIPRAMINA" },
                { rx: /\bEFEXOR\b/g, full: "VENLAFAXINA" },
                { rx: /\bPRISTIQ\b/g, full: "DESVENLAFAXINA" },
                { rx: /\bEXODUS\b/g, full: "ESCITALOPRAM" },
                { rx: /\bRECONTER\b/g, full: "ESCITALOPRAM" }
            ];
            for (let d of brandDict) { n = n.replace(d.rx, d.full); }
        }
        
        return n.replace(/\s+/g, ' ').trim(); 
    };

    // 📏 AUTO-AJUSTE REAL (MEDIDO): mede o quadrante numa "caixa de areia" invisível com o
    // tamanho EXATO de impressão (105mm x 148,5mm) e encontra, por busca binária, a maior
    // escala em que TODAS as medicações cabem sem serem cortadas pela data/assinatura.
    const RX_MIN_SCALE = 0.6;

    // Simula a tipografia que o enterprise.css aplica SOMENTE na impressão (@media print):
    // fonte Inter (mais larga que Arial) + line-height 1.5. Sem isso a tela "cabia" e o papel cortava.
    if (typeof document !== 'undefined' && !document.getElementById('rx-print-sim-css')) {
        const simCss = document.createElement('style');
        simCss.id = 'rx-print-sim-css';
        simCss.innerHTML = `
            .rx-print-sim .quadrante, .rx-print-sim .quadrante * { font-family: 'Inter', Arial, sans-serif !important; }
            .rx-print-sim .content-mini { line-height: 1.5 !important; }
            .rx-print-sim .header-text-center { line-height: 1.3 !important; }
            .rx-print-sim .poso-text { font-weight: 400 !important; }
        `;
        document.head.appendChild(simCss);
    }

    const rxMeasureOnce = function(quadHtml, simulatePrint) {
        const sb = document.createElement('div');
        sb.setAttribute('aria-hidden', 'true');
        if (simulatePrint) sb.className = 'rx-print-sim';
        sb.style.cssText = 'position:fixed;left:-30000px;top:0;width:105mm;height:148.5mm;visibility:hidden;overflow:hidden;pointer-events:none;z-index:-1;background:#fff;color:#000;display:block;';
        sb.innerHTML = quadHtml.replace(/__RXS__/g, '1');
        document.body.appendChild(sb);
        let result = 1;
        try {
            const cm = sb.querySelector('.content-mini');
            const inner = sb.querySelector('.rx-fit-inner');
            if (cm && inner && cm.clientHeight > 0) {
                const SAFE = 6; // folga para diferenças de renderização entre tela e impressora
                // Compara a altura NATURAL do conteúdo com o espaço disponível do quadro
                const fits = (s) => { cm.style.setProperty('--rx-s', String(s)); return inner.offsetHeight <= cm.clientHeight - SAFE; };
                if (!fits(1)) {
                    if (!fits(RX_MIN_SCALE)) {
                        result = RX_MIN_SCALE;
                    } else {
                        let lo = RX_MIN_SCALE, hi = 1;
                        for (let i = 0; i < 10; i++) {
                            const mid = (lo + hi) / 2;
                            if (fits(mid)) lo = mid; else hi = mid;
                        }
                        result = Math.floor(lo * 1000) / 1000;
                    }
                }
            }
        } catch (e) { result = 1; }
        finally { sb.remove(); }
        return result;
    };

    // Usa a MENOR escala entre a tipografia da tela e a da impressão (garante que caiba nos dois)
    const rxMeasureScale = function(quadHtml) {
        if (typeof document === 'undefined' || !document.body) return 1;
        return Math.min(rxMeasureOnce(quadHtml, false), rxMeasureOnce(quadHtml, true));
    };

    // Reajusta páginas já desenhadas (usado antes de imprimir e após o carregamento das fontes)
    const rxRefitAllPages = function() {
        if (typeof document === 'undefined') return;
        document.querySelectorAll('.a4-page[data-rx-scale]').forEach(page => {
            const q = page.querySelector('.quadrante');
            if (!q) return;
            const html = q.outerHTML.replace(/--rx-s:\s*[\d.]+/g, '--rx-s:__RXS__');
            const s = rxMeasureScale(html);
            page.setAttribute('data-rx-scale', String(s));
            page.querySelectorAll('.content-mini').forEach(cm => cm.style.setProperty('--rx-s', String(s)));
        });
    };
    if (typeof window !== 'undefined' && !window.__rxAutoFitHooked) {
        window.__rxAutoFitHooked = true;
        window.addEventListener('beforeprint', rxRefitAllPages);
        if (document.fonts) {
            try { document.fonts.load("400 12px Inter"); document.fonts.load("700 12px Inter"); document.fonts.load("italic 400 12px Inter"); } catch (e) {}
            document.fonts.ready.then(rxRefitAllPages).catch(() => {});
            if (document.fonts.addEventListener) document.fonts.addEventListener('loadingdone', rxRefitAllPages);
        }
    }

    // 💎 ESTÉTICA CLEAN DA RECEITA COMUM (DATA MAIS ALTA) 💎
    const masterPrescription = function(pageIndex, totalPages, showDate) {
        let limit = parseInt(localStorage.getItem('cerebrum_meds_limit'));
        if (isNaN(limit) || limit < 1 || limit > 8) limit = 5;

        const itemsSlice = this.items.slice(pageIndex * limit, (pageIndex * limit) + limit);
        const dateRaw = new Date();
        const monthName = dateRaw.toLocaleDateString('pt-BR', {month: 'long'});
        const monthCap = monthName.charAt(0).toUpperCase() + monthName.slice(1);
        const cityName = (this.config && this.config.city) ? this.config.city : "Feira de Santana";
        const dDay = String(dateRaw.getDate()).padStart(2, '0');
        const dMonth = String(dateRaw.getMonth() + 1).padStart(2, '0');
        const dYear = dateRaw.getFullYear();
        const isDateNumerico = localStorage.getItem('cerebrum_date_format') === 'numerico';
        const dataFormatada = isDateNumerico 
            ? `${cityName}, ${dDay}/${dMonth}/${dYear}`
            : `${cityName}, ${dateRaw.getDate()} de ${monthCap} de ${dYear}.`;
        const dataBranco = `${cityName}, _____/_____/______`;

        const usarManual = this.config && this.config.onlyFirstDate;
        const textoDataOutras = usarManual ? dataBranco : dataFormatada;
        const obsText = (pageIndex === totalPages - 1 && this.DOM.obsInput) ? this.DOM.obsInput.value.replace(/\n/g, '<br>') : '';
        const isHidden = pageIndex !== this.currentPage ? 'hidden' : '';
        const quadDateClass = showDate ? '' : 'invisible';

        let fMedBase = 12, fPoso = 11, mBot = 10, lHeight = 1.3, logoSize = 40, headFont = 10, patFont = 12.5, space = 8, footSpace = 15, quadPadV = 30, quadPadH = 38;
        if (limit === 6) { fMedBase = 12; fPoso = 10.5; mBot = 16; lHeight = 1.2; logoSize = 40; headFont = 10; patFont = 12.5; space = 12; footSpace = 30; quadPadV = 12; quadPadH = 34; }
        if (limit === 7) { fMedBase = 12; fPoso = 10; mBot = 10; lHeight = 1.15; logoSize = 40; headFont = 10; patFont = 12.5; space = 12; footSpace = 30; quadPadV = 10; quadPadH = 28; }
        if (limit >= 8) { fMedBase = 10.3; fPoso = 9.5;  mBot = 10; lHeight = 1.1; logoSize = 40; headFont = 10; patFont = 12.5; space = 12; footSpace = 30; quadPadV = 8; quadPadH = 24; }

        const userFontScale = parseFloat(localStorage.getItem('cerebrum_preview_font_scale') || 100) / 100;
        fMedBase *= userFontScale;
        fPoso *= userFontScale;

        // Todos os tamanhos da lista passam pela variável --rx-s (escala calculada pelo auto-ajuste)
        const S = (v) => `calc(${v}px * var(--rx-s, 1))`;
        // Espaçamentos encolhem mais rápido que as fontes (preserva a leitura)
        const SP = (v) => `calc(${v}px * var(--rx-s, 1) * var(--rx-s, 1))`;

        const listHtml = itemsSlice.map((it, idx) => {
            const safeUsage = (it.usage || "").replace(/ /g, '&nbsp;');
            const nameLen = it.med.length;
            let fMedDynamic = fMedBase;
            if (nameLen > 22) fMedDynamic = fMedBase * 0.90;
            if (nameLen > 30) fMedDynamic = fMedBase * 0.80;
            if (nameLen > 40) fMedDynamic = fMedBase * 0.70;

            let posoToRender = (it.poso || "").trim();
            if (!posoToRender && it.data && (it.data.customPoso || it.data.isCustomPoso)) {
                const cText = (it.data.customPoso || (typeof it.data.text === 'string' ? it.data.text : '')).trim();
                if (cText) {
                    posoToRender = /^uso:\s*/i.test(cText) ? cText : `Uso: ${cText}`;
                    if (!posoToRender.endsWith('.') && !posoToRender.endsWith('!')) posoToRender += '.';
                }
            }

            return `<div class="rx-med-item" style="margin-bottom:${SP(mBot)}; line-height:${lHeight};">
                        <div style="display: flex !important; align-items: flex-end !important; width: 100% !important;">
                            <span style="font-size: ${S(fMedDynamic)} !important; flex: 0 1 auto !important; max-width: 68% !important; word-break: break-word !important; white-space: normal !important; text-align: left !important; font-weight: bold !important; line-height: 1.1 !important;">
                                ${((pageIndex * limit) + idx + 1)}. ${it.med}
                            </span>
                            <div style="flex: 1 1 auto !important; border-bottom: 2px dotted #000 !important; margin: 0 6px 3px 6px !important; min-width: 10px !important;"></div>
                            <span style="font-size: ${S(fMedBase)} !important; flex: 0 0 auto !important; font-weight: bold !important; white-space: nowrap !important; text-align: right !important;">
                                ${safeUsage}
                            </span>
                        </div>
                        <span class="poso-text" style="font-size: ${S(fPoso)} !important; display:block; margin-top: ${S(3)}; margin-bottom: 0 !important; line-height:${lHeight};">${posoToRender}</span>
                    </div>`;
        }).join('');

        const safeName = (this.DOM.patientInput ? this.DOM.patientInput.value : "").toUpperCase();
        const signatureHtml = this.config && this.config.signature ? `<img src="${this.config.signature}" class="print-signature-img" style="position: absolute; bottom: 35px; left: 50%; transform: translateX(-50%); max-height: 45px; max-width: 160px; object-fit: contain; mix-blend-mode: multiply; z-index: 5; pointer-events: none;">` : '';
        
        const safeTitle = (this.config && this.config.title) ? this.config.title : '';
        const safeSub = (this.config && this.config.sub) ? `<br>${this.config.sub}` : '';
        const safeAddr = (this.config && this.config.addr) ? `<br>${this.config.addr.replace(/\n/g, '<br>')}` : '';
        
        let activeLogoPref = 'prefeitura.png';
        let activeLogoFarm = 'farmacia.png';
        try {
            const curUnit = (App.UnitsDB && typeof App.UnitsDB.getActiveUnit === 'function') ? App.UnitsDB.getActiveUnit() : null;
            if (curUnit) {
                if (curUnit.logoPref) activeLogoPref = curUnit.logoPref;
                if (curUnit.logoFarm) activeLogoFarm = curUnit.logoFarm;
            }
        } catch(e) {}

        const headerHtml = `<div class="header-mini" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:${space}px;"><img src="${activeLogoPref}" class="logo-img logo-img-left" style="max-height:${logoSize}px; object-fit:contain;"><div class="header-text-center" style="text-align:center; flex:1; font-size:${headFont}px; line-height:1.0; color:#000; font-weight:normal;">${safeTitle}${safeSub}${safeAddr}</div><img src="${activeLogoFarm}" class="logo-img logo-img-right" style="max-height:${logoSize}px; object-fit:contain;"></div>`;
        
        const patientHtml = `<div class="patient-block" style="font-size:${patFont}px; margin-bottom:${space}px; line-height:1.2;">Sr.(a): <b>${safeName}</b><br>End:<br><span class="r-symbol" style="display:inline-block; margin-top:0px; margin-bottom:0px; padding-bottom:0px; font-weight:bold; font-size:${patFont+2}px;">R/</span></div>`;
        const obsBlock = obsText ? `<div class="obs-block" style="font-size:${S(fPoso)} !important; margin-top:${S(mBot)} !important;"><b>Obs:</b> ${obsText}</div>` : '';
        
        // 🚀 MÁGICA AQUI: A data subiu! Margin-top menor (10px) e margin-bottom maior (30px) afastando do carimbo 🚀
        const dateHtml1 = `<div class="date-right ${quadDateClass}" style="text-align:right; font-size:${patFont}px; margin-top:10px; margin-bottom: 5px;">${dataFormatada}</div>`;
        const dateHtmlOthers = `<div class="date-right ${quadDateClass}" style="text-align:right; font-size:${patFont}px; margin-top:10px; margin-bottom: 5px;">${textoDataOutras}</div>`;

        const footerHtml = `<div class="footer-mini" style="position:relative; margin-top:10px; margin-bottom:25px; text-align:center; font-size:${patFont}px;">${signatureHtml}<div class="sig-line-mini" style="width:60%; border-top:1px solid #000; margin:0 auto 3px auto;"></div>Assinatura e carimbo</div>`;

        const content1 = `${patientHtml}<div class="content-mini" style="--rx-s:__RXS__; flex:1; min-height:0; overflow:hidden; padding-top:0px; margin-top:0px;"><div class="rx-fit-inner" style="display:flow-root;">${listHtml}${obsBlock}</div></div>${dateHtml1}${footerHtml}`;
        const contentOthers = `${patientHtml}<div class="content-mini" style="--rx-s:__RXS__; flex:1; min-height:0; overflow:hidden; padding-top:0px; margin-top:0px;"><div class="rx-fit-inner" style="display:flow-root;">${listHtml}${obsBlock}</div></div>${dateHtmlOthers}${footerHtml}`;

        const quadOpen = `<div class="quadrante" style="display:flex; flex-direction:column; padding:${quadPadV}px ${quadPadH}px !important; box-sizing:border-box;">`;
        const quad1Html = `${quadOpen}${headerHtml}${content1}</div>`;
        const quadOthersHtml = `${quadOpen}${headerHtml}${contentOthers}</div>`;

        // 📏 Mede no tamanho real de impressão e calcula a escala que faz tudo caber
        const rxScale = (itemsSlice.length > 0 || obsBlock) ? rxMeasureScale(quad1Html) : 1;
        if (rxScale <= RX_MIN_SCALE && typeof this.showNotification === 'function') {
            const now = Date.now();
            if (!this._rxFitWarnAt || now - this._rxFitWarnAt > 15000) {
                this._rxFitWarnAt = now;
                this.showNotification(`⚠️ Página ${pageIndex + 1}: textos muito longos. Reduza a quantidade de medicações por receita para melhor leitura.`, "warning");
            }
        }

        const pageHtml = `
            <div class="a4-page ${isHidden}" data-rx-scale="${rxScale}">
                ${quad1Html}
                ${quadOthersHtml}
                ${quadOthersHtml}
                ${quadOthersHtml}
            </div>`.replace(/__RXS__/g, String(rxScale));
            
        if(this.DOM.outputContainer) this.DOM.outputContainer.insertAdjacentHTML('beforeend', pageHtml);
    };

    // 💎 ESTÉTICA CLEAN DO LME (6 MESES) - DATA MAIS ALTA 💎
    const masterSixMonth = function(items, pageIndex, showDate) { 
        var isHidden = pageIndex !== this.currentPage ? 'hidden' : ''; 
        var dateRaw = new Date(); 
        var monthName = dateRaw.toLocaleDateString('pt-BR', {month: 'long'}); 
        var monthCap = monthName.charAt(0).toUpperCase() + monthName.slice(1); 
        var cityName = (this.config && this.config.city) ? this.config.city : "Feira de Santana";
        var dDay = String(dateRaw.getDate()).padStart(2, '0');
        var dMonth = String(dateRaw.getMonth() + 1).padStart(2, '0');
        var dYear = dateRaw.getFullYear();
        var isDateNumerico = localStorage.getItem('cerebrum_date_format') === 'numerico';
        var dataFormatada = isDateNumerico 
            ? cityName + ", " + dDay + "/" + dMonth + "/" + dYear
            : cityName + ", " + dateRaw.getDate() + " de " + monthCap + " de " + dYear + ".";
        
        var quad1DateClass = showDate ? '' : 'invisible'; 
        var quadOthersDateClass = (showDate && (!this.config || !this.config.onlyFirstDate)) ? '' : 'invisible'; 

        var limitLME = items.length;
        var fMedBase = 11, fPoso = 10, mBot = 10, lHeight = 1.2; 
        var logoSize = 40, headFont = 10, patFont = 12, space = 12, footSpace = 15, quadPadV = 15, quadPadH = 38;

        if (limitLME === 6) { 
            fMedBase = 10.5; fPoso = 9.5; mBot = 8; lHeight = 1.15; 
            logoSize = 34; headFont = 9; patFont = 11; space = 8; footSpace = 10; quadPadV = 12; quadPadH = 34;
        }
        if (limitLME >= 7) { 
            fMedBase = 9.5; fPoso = 8.5; mBot = 5; lHeight = 1.1; 
            logoSize = 28; headFont = 8; patFont = 10; space = 5; footSpace = 5; quadPadV = 10; quadPadH = 28;
        }

        var userFontScale = parseFloat(localStorage.getItem('cerebrum_preview_font_scale') || 100) / 100;
        fMedBase *= userFontScale;
        fPoso *= userFontScale;
        
        var recipeContent = items.map(function(item, i) { 
            var qty6Months = 0, unitType = "comprimidos"; 
            if (item.data && item.data.type === 'INJECT') { 
                qty6Months = Math.ceil((180 / (item.data.t || 30)) * (item.data.m || 1)); 
                unitType = "ampolas"; 
            } else if (item.data) { 
                qty6Months = Math.ceil(((parseFloat(item.data.m)||0) + (parseFloat(item.data.t)||0) + (parseFloat(item.data.n)||0)) * 180); 
            } 
            
            var safeUsageLME = (qty6Months + ' ' + unitType).replace(/ /g, '&nbsp;');

            var nameLen = item.med.length;
            var fMedDynamic = fMedBase;
            if (nameLen > 22) fMedDynamic = fMedBase * 0.90;
            if (nameLen > 30) fMedDynamic = fMedBase * 0.80;
            if (nameLen > 40) fMedDynamic = fMedBase * 0.70;

            return '<div style="margin-bottom:' + mBot + 'px; line-height:' + lHeight + ';">' +
                        '<div style="display: flex !important; align-items: flex-end !important; width: 100% !important;">' +
                            '<span style="font-size: ' + fMedDynamic + 'px !important; flex: 0 1 auto !important; max-width: 68% !important; line-height: 1.1 !important; word-break: break-word !important; white-space: normal !important; text-align: left !important; font-weight: bold !important;">' + 
                                (i + 1) + '. ' + item.med + 
                            '</span>' +
                            '<div style="flex: 1 1 auto !important; border-bottom: 2px dotted #000 !important; margin: 0 5px 3px 5px !important; min-width: 10px !important;"></div>' +
                            '<span style="font-size: ' + fMedBase + 'px !important; flex: 0 0 auto !important; font-weight: bold !important; white-space: nowrap !important; text-align: right !important;">' + 
                                safeUsageLME + 
                            '</span>' +
                        '</div>' +
                        '<span class="poso-text" style="display:block; margin-top:3px; font-size:10px;">Uso: ' + item.poso + ' (Qtd para 6 meses)</span>' +
                    '</div>'; 
        }).join(''); 
        
        var safeName = (this.lmeData && this.lmeData.patientName) ? this.lmeData.patientName : ((this.DOM.patientInput ? this.DOM.patientInput.value : "").toUpperCase());
        var signatureHtml = this.config && this.config.signature ? '<img src="' + this.config.signature + '" style="position: absolute; bottom: 35px; left: 50%; transform: translateX(-50%); max-height: 45px; max-width: 160px; object-fit: contain; mix-blend-mode: multiply; z-index: 5; pointer-events: none;">' : '';
        
        const safeTitle = this.config && this.config.title ? this.config.title : '';
        const safeSub = this.config && this.config.sub ? '<br>' + this.config.sub : '';
        const safeAddr = this.config && this.config.addr ? '<br>' + this.config.addr.replace(/\n/g, '<br>') : '';
        
        let activeLogoPrefSix = 'prefeitura.png';
        let activeLogoFarmSix = 'farmacia.png';
        try {
            const curUnit = (App.UnitsDB && typeof App.UnitsDB.getActiveUnit === 'function') ? App.UnitsDB.getActiveUnit() : null;
            if (curUnit) {
                if (curUnit.logoPref) activeLogoPrefSix = curUnit.logoPref;
                if (curUnit.logoFarm) activeLogoFarmSix = curUnit.logoFarm;
            }
        } catch(e) {}

        const headerHtml = `<div class="header-mini" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:${space}px;"><img src="${activeLogoPrefSix}" class="logo-img logo-img-left" style="max-height:${logoSize}px; object-fit:contain;"><div class="header-text-center" style="text-align:center; flex:1; font-size:${headFont}px; line-height:1.0; color:#000; font-weight:normal;">${safeTitle}${safeSub}${safeAddr}</div><img src="${activeLogoFarmSix}" class="logo-img logo-img-right" style="max-height:${logoSize}px; object-fit:contain;"></div>`;
        
        var patientHtml = '<div class="patient-block" style="font-size:' + patFont + 'px; margin-bottom:' + space + 'px; line-height:1.2;">Sr.(a): <b>' + safeName + '</b><br>End:<br><span class="r-symbol" style="display:inline-block; margin-top:0px; margin-bottom:0px; padding-bottom:0px; font-weight:bold; font-size:' + (patFont+2) + 'px;">R/</span></div>';
        
        // 🚀 Data também rebaixada no LME 🚀
        var dateHtml1 = `<div class="date-right ${quad1DateClass}" style="text-align:right; font-size:${patFont}px; margin-top:10px; margin-bottom:30px;">${dataFormatada}</div>`;
        var dateHtmlOthers = `<div class="date-right ${quadOthersDateClass}" style="text-align:right; font-size:${patFont}px; margin-top:10px; margin-bottom:30px;">${dataFormatada}</div>`;
        
        var footerHtml = '<div class="footer-mini" style="position:relative; margin-top:10px; margin-bottom:25px; text-align:center; font-size:'+patFont+'px;">' + signatureHtml + '<div class="sig-line-mini" style="width:60%; border-top:1px solid #000; margin:0 auto 3px auto;"></div>Assinatura e carimbo</div>';

        var content1 = patientHtml + '<div class="content-mini" style="flex:1; min-height:0; overflow:hidden;">' + recipeContent + '</div>' + dateHtml1 + footerHtml;
        var contentOthers = patientHtml + '<div class="content-mini" style="flex:1; min-height:0; overflow:hidden;">' + recipeContent + '</div>' + dateHtmlOthers + footerHtml;

        var pageHtml = 
            '<div class="a4-page ' + isHidden + '">' +
                '<div class="quadrante" style="display:flex; flex-direction:column; padding:' + quadPadV + 'px ' + quadPadH + 'px !important; box-sizing:border-box;">' + headerHtml + content1 + '</div>' +
                '<div class="quadrante" style="display:flex; flex-direction:column; padding:' + quadPadV + 'px ' + quadPadH + 'px !important; box-sizing:border-box;">' + headerHtml + contentOthers + '</div>' +
                '<div class="quadrante" style="display:flex; flex-direction:column; padding:' + quadPadV + 'px ' + quadPadH + 'px !important; box-sizing:border-box;">' + headerHtml + contentOthers + '</div>' +
                '<div class="quadrante" style="display:flex; flex-direction:column; padding:' + quadPadV + 'px ' + quadPadH + 'px !important; box-sizing:border-box;">' + headerHtml + contentOthers + '</div>' +
            '</div>'; 
        if(this.DOM.outputContainer) this.DOM.outputContainer.insertAdjacentHTML('beforeend', pageHtml); 
    };

    // 💎 ESTÉTICA CLEAN DA FOLHA DE EXAMES 💎
    const masterExams = function(pageIndex) {
        if (!this.selectedExams || this.selectedExams.size === 0) return;

        const isHidden = pageIndex !== this.currentPage ? 'hidden' : '';

        const dateRaw = new Date();
        const monthName = dateRaw.toLocaleDateString('pt-BR', {month: 'long'});
        const monthCap = monthName.charAt(0).toUpperCase() + monthName.slice(1);
        const city = this.config && this.config.city ? this.config.city : "Feira de Santana";
        const dataExtenso = `${city}, ${dateRaw.getDate()} de ${monthCap} de ${dateRaw.getFullYear()}`;
        const safeName = (this.DOM.patientInput ? this.DOM.patientInput.value : "").toUpperCase();

        const examsHtml = Array.from(this.selectedExams).map(ex => `<li style="margin-bottom: 8px;">${ex}</li>`).join('');
        const justHtml = this.examJustification ? `<div style="margin-top: 30px; font-size: 11pt; border-top: 1px dashed #ccc; padding-top: 15px;"><b>Justificativa Clínica:</b><br>${this.examJustification.replace(/\n/g, '<br>')}</div>` : '';

        const signatureHtml = (this.config && this.config.signature) 
            ? `<img src="${this.config.signature}" class="print-signature-img" style="bottom: 25px;">` 
            : '';

        const safeTitle = this.config && this.config.title ? this.config.title : '';
        const safeSub = this.config && this.config.sub ? '<br>' + this.config.sub : '';
        const safeAddr = this.config && this.config.addr ? '<br>' + this.config.addr.replace(/\n/g, '<br>') : '';

        let activeLogoPrefExam = 'prefeitura.png';
        let activeLogoFarmExam = 'farmacia.png';
        try {
            const curUnit = (App.UnitsDB && typeof App.UnitsDB.getActiveUnit === 'function') ? App.UnitsDB.getActiveUnit() : null;
            if (curUnit) {
                if (curUnit.logoPref) activeLogoPrefExam = curUnit.logoPref;
                if (curUnit.logoFarm) activeLogoFarmExam = curUnit.logoFarm;
            }
        } catch(e) {}

        let content = `
        <div style="width: 100%; height: 100%; padding: 18mm 30mm; display: flex; flex-direction: column; box-sizing: border-box; background: white; color: black; font-family: Arial, sans-serif;">
            
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 30px; padding-bottom: 5px; flex-shrink: 0;">
                <img src="${activeLogoPrefExam}" class="logo-img-left" style="width: 3cm; height: 3cm; object-fit: contain;" onerror="if(this.src.includes('png')){this.src='prefeitura.jpg';}else{this.style.opacity=0;}">
                <div style="text-align: center; flex: 1; font-size: 11pt; line-height: 1.0; color: #000; padding: 0 15px; font-weight: normal;">
                    ${safeTitle}${safeSub}${safeAddr}
                </div>
                <img src="${activeLogoFarmExam}" class="logo-img-right" style="width: 3cm; height: 3cm; object-fit: contain;" onerror="if(this.src.includes('png')){this.src='farmacia.jpg';}else{this.style.opacity=0;}">
            </div>

            <div style="flex-shrink: 0; margin-bottom: 25px; font-size: 12pt;">
                Paciente: <b>${safeName}</b>
            </div>
            
            <div style="text-align: center; font-size: 14pt; font-weight: bold; margin-bottom: 35px; text-transform: uppercase; flex-shrink: 0; letter-spacing: 1px;">
                SOLICITAÇÃO DE EXAMES MÉDICOS
            </div>

            <div style="flex-grow: 1; font-size: 11pt; line-height: 1.5; display: flex; flex-direction: column;">
                <ul style="column-count: 2; column-gap: 40px; margin: 0; padding-left: 20px; flex-grow: 1;">
                    ${examsHtml}
                </ul>
                ${justHtml}
            </div>

            <div style="flex-shrink: 0; margin-top: 40px; margin-bottom: 20px;">
                <div style="text-align: right; font-size: 12pt; margin-bottom: 40px;">${dataExtenso}</div>
                <div style="text-align: center; font-size: 12pt; position: relative;">
                    ${signatureHtml}
                    <div style="width: 10cm; border-top: 1px solid #000; margin: 0 auto 5px;"></div>
                    Assinatura e carimbo do prescritor
                </div>
            </div>
        </div>`;
        
        const pageHtml = `<div class="lme-bg-page ${isHidden}">${content}</div>`; 
        
        if(this.DOM.outputContainer) this.DOM.outputContainer.insertAdjacentHTML('beforeend', pageHtml);
    };

    // A FOLHA DE INTERNAMENTO
    const masterWard = function(globalPageIndex, wardPageIndex = 0) {
        const isHidden = globalPageIndex !== this.currentPage ? 'hidden' : '';
        const patientName = document.getElementById('patient-name')?.value.toUpperCase() || '';
        const signature = (this.config && this.config.signature) ? `<img src="${this.config.signature}" style="position:absolute; bottom:14.5%; left:14.5%; max-width:160px; max-height:45px; object-fit:contain; mix-blend-mode:multiply; z-index:5; pointer-events:none;">` : '';

        const today = new Date();
        const dd = String(today.getDate()).padStart(2, '0');
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const yyyy = today.getFullYear();

        const formatNum = (val) => { 
            let v = parseFloat(val) || 0;
            if (v === 0) return "00";
            if (v < 10 && Number.isInteger(v)) return "0" + v;
            if (v === 0.25) return "1/4"; if (v === 0.5) return "1/2"; if (v === 0.75) return "3/4";
            return v.toString().replace('.', ',');
        };

        let medRows = '';
        const startY = 41; 
        const stepY = 4.5; 
        const itemsSlice = this.items.slice(wardPageIndex * 9, (wardPageIndex * 9) + 9);

        itemsSlice.forEach((item, index) => {
            const y = startY + (index * stepY);
            let medName = item.med.toUpperCase().replace(/\s*\(\s*(COMP|GOTAS\/ML|AMP\/INJ|COMPRIMIDOS?|GOTAS|AMPOLAS?)\s*\)\s*$/i, '');
            const isSOS = (item.data && item.data.type === 'SOS');

            if (isSOS) {
                let sosText = item.med.replace("FENERGAM 25MG/ML, AMBOS", "FENERGAM 25MG/ML,<br>AMBOS");
                let fMedSos = 10;
                if (sosText.length > 50) fMedSos = 8.5;
                medRows += `<div class="ward-item-text" style="position: absolute; top: ${y}%; left: 6.8%; width: 85%; display: flex; align-items: center; white-space: normal !important;"><span style="font-size: ${fMedSos}px; font-weight: 800; color: #000; line-height: 1.1;">${sosText}</span></div>`;
            } else {
                const isInject = (item.data && item.data.type === 'INJECT') || medName.match(/\b(INJ|INJET[AÁ]VEL|AMPOLA|DECANOATO)\b/i);
                if (isInject) {
                    const qty = parseFloat(item.data?.m) || 0;
                    const days = parseFloat(item.data?.t) || 0;
                    const ampLabel = qty > 1 ? "AMPOLAS" : "AMPOLA";
                    let via = "INTRAMUSCULAR";
                    if (medName.match(/\bIV\b|\bEV\b|\bINTRAVENOSA\b/i)) via = "INTRAVENOSA";
                    else if (medName.match(/\bSC\b|\bSUBCUT[AÂ]NEA\b/i)) via = "SUBCUTÂNEA";
                    const posoInject = `USO: ${formatNum(qty)} ${ampLabel} POR VIA ${via} A CADA ${formatNum(days)} DIAS.`;
                    
                    let fMedInj = 11;
                    if (medName.length > 25) fMedInj = 9.5;
                    if (medName.length > 32) fMedInj = 8.5;

                    medRows += `<div class="ward-item-text" style="position: absolute; top: ${y}%; left: 6.8%; width: 44%; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; white-space: normal !important;"><span style="font-size: ${fMedInj}px; font-weight: 900; color: #000; line-height: 1.1; max-width: 100%; word-break: break-word;">${medName}</span><span style="font-size: 8px; font-weight: normal; color: #000; margin-top: 1px;">${posoInject}</span></div>`;
                } else {
                    let m = formatNum(item.data?.m); let t = formatNum(item.data?.t); let n = formatNum(item.data?.n);
                    let posoCompacta = `${m} &nbsp;&nbsp;-&nbsp;&nbsp; ${t} &nbsp;&nbsp;-&nbsp;&nbsp; ${n}`;
                    let fMedPill = 12;
                    if (medName.length > 22) fMedPill = 10.5;
                    if (medName.length > 30) fMedPill = 9.0;
                    if (medName.length > 40) fMedPill = 8.0;

                    medRows += `<div class="ward-item-text" style="position: absolute; top: ${y}%; left: 6.8%; width: 44%; display: flex; justify-content: space-between; align-items: center; padding-right: 5px; white-space: normal !important;"><span style="flex: 1 1 auto; font-size: ${fMedPill}px; font-weight: 900; color: #000; line-height: 1.1; max-width: 65%; word-break: break-word; text-align: left;">${medName}</span><span style="flex: 0 0 auto; font-size: 13px; font-weight: 900; color: #000; letter-spacing: 1px; white-space: nowrap; text-align: right;">${posoCompacta}</span></div>`;
                }
            }
        });

        const posDia = "18.5%", posMes = "22.5%", posAno = "26.0%";
        
        const fullHtml = `
            <div class="ward-print-wrapper ${isHidden}">
                <div class="ward-landscape-page">
                    <img src="PRESCRIÇÃO MÉDICA ATUALIZADA_page-0001.jpg" class="ward-bg-img" onerror="this.style.display='none';">
                    <div style="position:absolute; z-index:10; font-weight:900; font-size:22px; color:black; top:17.0%; left:10.5%; width:58%; text-transform:uppercase;">${patientName}</div>
                    <input type="text" class="ward-prontuario-input sync-pront-all" style="position:absolute; z-index:999 !important; top:15.5%; left:81%; width:15%; border:none; background:transparent; font-size:22px; font-weight:900; color:#000 !important; text-align:center; outline:none;" placeholder="---">
                    ${medRows}
                    ${signature}
                    <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posDia};">${dd}</div>
                    <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posMes};">${mm}</div>
                    <div style="position:absolute; z-index:99; font-weight:bold; font-size:15px; color:black; bottom:8.0%; left:${posAno};">${yyyy}</div>
                </div>
            </div>`;
            
        if(this.DOM.outputContainer) this.DOM.outputContainer.insertAdjacentHTML('beforeend', fullHtml);
    };

    // 3. O DEBOUNCER SUPREMO (Agrupa os múltiplos App.render dos temporizadores antigos)
    let renderTimer = null;
    const ultimateRender = function() {
        if (renderTimer) clearTimeout(renderTimer);
        
        renderTimer = setTimeout(() => {
            if (!this.DOM || !this.DOM.uiList) return;

            if (typeof this._lastItemCount === 'undefined') this._lastItemCount = this.items.length;
            const currentCount = this.items.length;
            if (this._lastItemCount > 0 && currentCount === 0) {
                this.includeWardSheet = false;
                this.pageDateStates = {}; 
                const wardBtn = document.getElementById('btn-ward-sheet') || document.querySelector('[onclick*="toggleWard"]');
                if (wardBtn) { wardBtn.classList.remove('active'); wardBtn.style.backgroundColor = ''; }
                const patName = document.getElementById('patient-name'); if (patName) patName.value = '';
                const prontInputs = document.querySelectorAll('.ward-prontuario-input'); prontInputs.forEach(inp => inp.value = '');
            }
            this._lastItemCount = currentCount; 

            this.items.forEach(it => {
                if (it.med && it.med.match(/\b(SOS|CONTENÇÃO|CONTENCAO|SE APM|MECÂNICA|MECANICA)\b/i)) {
                    if (!it.data) it.data = {}; it.data.type = 'SOS';
                }
            });
            const normals = this.items.filter(it => !(it.data && it.data.type === 'SOS'));
            const soses = this.items.filter(it => it.data && it.data.type === 'SOS');
            this.items = [...normals, ...soses]; 

            this.DOM.uiList.innerHTML = this.items.map((it, i) => `<div class="item-row" draggable="true" data-index="${i}" oncontextmenu="App.showContextMenu(event, ${i})"><div class="item-row-content"><span>${it.med}</span><div class="row-actions"><button class="btn-icon btn-copy-row" onclick="App.copySingleMed(${i}); event.stopPropagation();" title="Copiar esta medicação (formato rápido)">📋</button><button class="btn-icon" onclick="App.loadItemForEdit(${i})" title="Editar">✏️</button><button class="btn-icon btn-del" onclick="App.items.splice(${i},1);App.render()" title="Remover">×</button></div></div></div>`).join(''); 
            const prevActions = document.getElementById('preview-floating-actions');
            if (prevActions) {
                if (this.items && this.items.length > 0) prevActions.classList.remove('hidden');
                else prevActions.classList.add('hidden');
            }
            const btnBatch = document.getElementById('btn-batch-lme'); 
            if(btnBatch) btnBatch.classList.toggle('hidden', !this.items.some(item => typeof this.isHighCost === 'function' && this.isHighCost(item.med))); 

            if(this.DOM.outputContainer) this.DOM.outputContainer.innerHTML = ""; 

            let groupedHighCost = {}; 
            if (this.lmeData && this.lmeData.active && typeof this.groupHighCostItems === 'function') { 
                groupedHighCost = this.groupHighCostItems(this.lmeData.items); 
            } 
            const hasLME = Object.keys(groupedHighCost).length > 0;
            
            let limit = parseInt(localStorage.getItem('cerebrum_meds_limit'));
            if (isNaN(limit) || limit < 1 || limit > 8) limit = 5;

            let totalPagesPrescription = Math.ceil(normals.length / limit); 
            const hasExams = this.selectedExams && this.selectedExams.size > 0;
            const wardPagesCount = this.includeWardSheet ? Math.max(1, Math.ceil(this.items.length / 9)) : 0;
            
            if (totalPagesPrescription === 0 && !hasExams && !hasLME && wardPagesCount === 0) { totalPagesPrescription = 1; }
            const totalPages = totalPagesPrescription + (Object.keys(groupedHighCost).length * 2) + (hasExams ? 1 : 0) + wardPagesCount; 
            if (this.currentPage >= totalPages) this.currentPage = totalPages > 0 ? totalPages - 1 : 0; 
            
            const originalItems = this.items;
            this.items = normals;
            
            const autoDate = localStorage.getItem('cerebrum_auto_date') !== 'false';

            for (let p = 0; p < totalPagesPrescription; p++) { 
                if (this.pageDateStates[p] === undefined) this.pageDateStates[p] = autoDate; 
                App.renderPrescriptionPage.call(this, p, totalPagesPrescription, this.pageDateStates[p]); 
            } 
            
            this.items = originalItems;
            let indexOffset = totalPagesPrescription;
            
            if (hasLME) { 
                Object.keys(groupedHighCost).forEach(groupName => { 
                    if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate; 
                    if (this.renderSixMonthRecipe) this.renderSixMonthRecipe(groupedHighCost[groupName], indexOffset, this.pageDateStates[indexOffset]); 
                    if (this.pageDateStates[indexOffset + 1] === undefined) this.pageDateStates[indexOffset + 1] = autoDate; 
                    if (this.renderLMEPage) this.renderLMEPage(groupedHighCost[groupName], groupName, indexOffset + 1, this.pageDateStates[indexOffset + 1]); 
                    indexOffset += 2; 
                }); 
            } 
            
            if (hasExams) { 
                if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate;
                if (this.renderExamsPage) this.renderExamsPage(indexOffset); 
                indexOffset += 1; 
            }

            if (wardPagesCount > 0) {
                for (let wp = 0; wp < wardPagesCount; wp++) {
                    if (this.pageDateStates[indexOffset] === undefined) this.pageDateStates[indexOffset] = autoDate;
                    App.renderWardPage.call(this, indexOffset, wp);
                    indexOffset += 1;
                }
            }

            const sosBtn = document.getElementById('btn-sos-module');
            if (sosBtn) {
                const trueWardStart = totalPagesPrescription + (hasLME ? Object.keys(groupedHighCost).length * 2 : 0) + (hasExams ? 1 : 0);
                const isOnWardPage = this.includeWardSheet && (this.currentPage >= trueWardStart);
                sosBtn.style.display = isOnWardPage ? 'block' : 'none';
            }
            
            const navControls = document.getElementById('nav-controls'); 
            if (navControls) navControls.classList.remove('hidden'); 
            const pageInd = document.getElementById('page-indicator'); 
            if (pageInd) pageInd.innerText = `Página ${this.currentPage + 1} de ${totalPages || 1}`; 
            const prevPage = document.getElementById('prev-page'); 
            if (prevPage) prevPage.disabled = this.currentPage === 0; 
            const nextPage = document.getElementById('next-page'); 
            if (nextPage) nextPage.disabled = this.currentPage >= (totalPages || 1) - 1; 
            if (window.updatePageNavPills) window.updatePageNavPills();
            if (this.DOM.dateCheck) this.DOM.dateCheck.checked = !!this.pageDateStates[this.currentPage];

            setTimeout(() => {
                const syncInputs = document.querySelectorAll('.sync-pront-all');
                syncInputs.forEach(inp => {
                    inp.addEventListener('input', (e) => {
                        syncInputs.forEach(other => { 
                            if (other !== inp) { other.value = e.target.value; other.setAttribute('value', e.target.value); }
                        });
                    });
                });
                if (typeof App.refreshEditorState === 'function') App.refreshEditorState();
                if (typeof App.applyFinalLockRules === 'function') App.applyFinalLockRules();
            }, 50);
        }, 150); 
    };

    // 4. CONGELAMENTO ABSOLUTO DE FUNÇÕES (Blindado contra TypeError em modo estrito)
    const lock = (prop, func) => {
        try {
            Object.defineProperty(App, prop, {
                get() { return func; },
                set(v) { /* ignora silenciosamente tentativas legadas de sobrescrever */ },
                configurable: true,
                enumerable: true
            });
        } catch(e) {
            App[prop] = func;
        }
    };

    lock('render', ultimateRender);
    lock('renderPrescriptionPage', masterPrescription);
    lock('renderSixMonthRecipe', masterSixMonth);
    lock('renderExamsPage', masterExams);
    lock('renderWardPage', masterWard);
    lock('expandMedName', ultimateExpandMed);

    if (App.items) App.render();


})();
